(15, 1, '2026-01-31 17:59:25', '2026-01-31 08:59:25', '<!-- wp:group {\"metadata\":{\"categories\":[\"header\"],\"patternName\":\"core/simple-header-with-tagline\",\"name\":\"Simple header with tagline\"},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|30\"}},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|contrast\"}}}},\"textColor\":\"contrast\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-contrast-color has-text-color has-link-color\" style=\"padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--30)\"><!-- wp:group {\"align\":\"wide\",\"layout\":{\"type\":\"flex\",\"justifyContent\":\"left\",\"flexWrap\":\"wrap\"}} -->\n<div class=\"wp-block-group alignwide\"><!-- wp:site-logo {\"width\":178,\"shouldSyncIcon\":true} /-->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"24px\"}},\"layout\":{\"type\":\"flex\"}} -->\n<div class=\"wp-block-group\"></div>\n<!-- /wp:group -->\n\n<!-- wp:navigation {\"ref\":4,\"fontSize\":\"small\",\"layout\":{\"type\":\"flex\",\"setCascadingProperties\":true,\"justifyContent\":\"right\"}} /--></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:cover {\"url\":\"https://lptemp.com/dx/wp-content/uploads/2020/01/head003_bg.jpg\",\"dimRatio\":0,\"overlayColor\":\"white\",\"contentPosition\":\"center center\",\"align\":\"full\",\"className\":\"is-light is-position-center-center colorful-headParts\"} -->\n<div class=\"wp-block-cover alignfull is-light is-position-center-center colorful-headParts\"><img class=\"wp-block-cover__image-background\" alt=\"\" src=\"https://lptemp.com/dx/wp-content/uploads/2020/01/head003_bg.jpg\" data-object-fit=\"cover\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-white-background-color has-background-dim-0 has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:columns {\"style\":{\"color\":{\"text\":\"#313131\"}}} -->\n<div class=\"wp-block-columns has-text-color\" style=\"color:#313131\"><!-- wp:column {\"className\":\"is-style-padding\"} -->\n<div class=\"wp-block-column is-style-padding\"><!-- wp:heading {\"textAlign\":\"left\",\"className\":\"medium-text\",\"textColor\":\"vivid-red\"} -->\n<h2 class=\"wp-block-heading has-text-align-left medium-text has-vivid-red-color has-text-color\">ヘッドテキストを入力</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"textAlign\":\"left\",\"className\":\"large-text\"} -->\n<h2 class=\"wp-block-heading has-text-align-left large-text\">ヘッドテキストを入力</h2>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"opacity\":\"css\",\"className\":\"is-style-default\",\"style\":{\"color\":{\"background\":\"#e32924\"}}} -->\n<hr class=\"wp-block-separator has-text-color has-css-opacity has-background is-style-default\" style=\"background-color:#e32924;color:#e32924\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"align\":\"left\"} -->\n<p class=\"has-text-align-left\">テキストを入力テキストを入力テキストを入力<br>ヘッドパーツのテキストを改行する時は、レイアウト崩れを防ぐため「Shiftキー」を押しながら改行を行って下さい 右の画像スタイルは「COLORFUL 枠＋影」です</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"className\":\"is-style-padding\"} -->\n<div class=\"wp-block-column is-style-padding\"><!-- wp:image {\"sizeSlug\":\"large\",\"className\":\"is-style-shadow-border\"} -->\n<figure class=\"wp-block-image size-large is-style-shadow-border\"><img src=\"https://lptemp.com/dx/wp-content/uploads/2020/01/insert-image.jpg\" alt=\"\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:cover {\"overlayColor\":\"white\",\"isUserOverlayColor\":true,\"contentPosition\":\"center center\",\"isDark\":false,\"align\":\"full\",\"className\":\"is-position-center-center\"} -->\n<div class=\"wp-block-cover alignfull is-light is-position-center-center\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-white-background-color has-background-dim-100 has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:group {\"className\":\"colorful_cover_inner\",\"style\":{\"color\":{\"text\":\"#333333\"}}} -->\n<div class=\"wp-block-group colorful_cover_inner has-text-color\" style=\"color:#333333\"><!-- wp:group {\"className\":\"colorful_Heading_New_Basic\"} -->\n<div class=\"wp-block-group colorful_Heading_New_Basic\"><!-- wp:heading {\"textAlign\":\"center\",\"className\":\"large-size-heading\"} -->\n<h2 class=\"wp-block-heading has-text-align-center large-size-heading\" id=\"こんな悩みありませんか\">こんな悩みありませんか？</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:separator {\"opacity\":\"css\"} -->\n<hr class=\"wp-block-separator has-css-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:spacer {\"height\":\"30px\"} -->\n<div style=\"height:30px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"is-style-shadow-B\",\"style\":{\"color\":{\"background\":\"#f6f6f6\"}}} -->\n<div class=\"wp-block-group is-style-shadow-B has-background\" style=\"background-color:#f6f6f6\"><!-- wp:paragraph -->\n<p>〜〜〜ができない</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"15px\"} -->\n<div style=\"height:15px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"className\":\"is-style-shadow-B\",\"style\":{\"color\":{\"background\":\"#f6f6f6\"}}} -->\n<div class=\"wp-block-group is-style-shadow-B has-background\" style=\"background-color:#f6f6f6\"><!-- wp:paragraph -->\n<p>〜〜〜ができない</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"15px\"} -->\n<div style=\"height:15px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"className\":\"is-style-shadow-B\",\"style\":{\"color\":{\"background\":\"#f6f6f6\"}}} -->\n<div class=\"wp-block-group is-style-shadow-B has-background\" style=\"background-color:#f6f6f6\"><!-- wp:paragraph -->\n<p>〜〜〜ができない</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:image {\"id\":4628,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"is-style-rounded mg-20\"} -->\n<figure class=\"wp-block-image size-large is-style-rounded mg-20\"><img src=\"https://lptemp.com/dx/wp-content/uploads/2021/12/worrying-1024x1024-1.jpg\" alt=\"\" class=\"wp-image-4628\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"is-style-shadow-B\",\"style\":{\"color\":{\"background\":\"#f6f6f6\"}}} -->\n<div class=\"wp-block-group is-style-shadow-B has-background\" style=\"background-color:#f6f6f6\"><!-- wp:paragraph -->\n<p>〜〜〜ができない</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"15px\"} -->\n<div style=\"height:15px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"className\":\"is-style-shadow-B\",\"style\":{\"color\":{\"background\":\"#f6f6f6\"}}} -->\n<div class=\"wp-block-group is-style-shadow-B has-background\" style=\"background-color:#f6f6f6\"><!-- wp:paragraph -->\n<p>〜〜〜ができない</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"15px\"} -->\n<div style=\"height:15px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"className\":\"is-style-shadow-B\",\"style\":{\"color\":{\"background\":\"#f6f6f6\"}}} -->\n<div class=\"wp-block-group is-style-shadow-B has-background\" style=\"background-color:#f6f6f6\"><!-- wp:paragraph -->\n<p>〜〜〜ができない</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"30px\"} -->\n<div style=\"height:30px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"className\":\"small-size-heading\"} -->\n<h2 class=\"wp-block-heading has-text-align-center small-size-heading\" id=\"〇〇なら-そんなあなたの悩みを解消し-このような未来にいく事ができます\">〇〇なら、<br>そんなあなたの悩みを解消し、<br>このような未来にいく事ができます。</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">or　その悩み、〇〇が解決します</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">or　1つでも当てはまるなら、〇〇をぜひお試しください。</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:cover {\"customOverlayColor\":\"#f3f3f3\",\"isUserOverlayColor\":true,\"contentPosition\":\"center center\",\"isDark\":false,\"align\":\"full\",\"className\":\"is-position-center-center\"} -->\n<div class=\"wp-block-cover alignfull is-light is-position-center-center\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-100 has-background-dim\" style=\"background-color:#f3f3f3\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:group {\"className\":\"colorful_Heading_New_Basic is-style-default\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n<div class=\"wp-block-group colorful_Heading_New_Basic is-style-default\"><!-- wp:spacer {\"height\":\"40px\"} -->\n<div style=\"height:40px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"className\":\"large-size-heading is-style-default\",\"style\":{\"typography\":{\"lineHeight\":\"1.2\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center large-size-heading is-style-default\" style=\"line-height:1.2\">このサービスを受けると<br>こんな効果を得られます</h2>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"40px\"} -->\n<div style=\"height:40px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">こちらのセクションは４つのカラムで構成されているベネフィットセクションです。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">タブレット・スマートフォンのサイズになると、1カラムのコンテンツが４つ並ぶように配置されます。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">全体の横幅は1200pxで指定されてますが、横幅変更の際には</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">グループ→設定内の「レイアウト」→「コンテント幅を使用するインナーブロック」</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">からコンテンツの横幅を指定し直してください。</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"40px\"} -->\n<div style=\"height:40px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":3} -->\n<h3 class=\"wp-block-heading has-text-align-center\">ベネフィット<br>その１</h3>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"10px\"} -->\n<div style=\"height:10px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:image {\"id\":6872,\"width\":\"75px\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"https://lptemp.com/dx/wp-content/uploads/note-icon.png\" alt=\"\" class=\"wp-image-6872\" style=\"width:75px\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:spacer {\"height\":\"10px\"} -->\n<div style=\"height:10px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>ベネフィットの文章を入力してください。ベネフィットの文章を入力してください。</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":3} -->\n<h3 class=\"wp-block-heading has-text-align-center\">ベネフィット<br>その２</h3>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"10px\"} -->\n<div style=\"height:10px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:image {\"id\":6872,\"width\":\"75px\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"https://lptemp.com/dx/wp-content/uploads/note-icon.png\" alt=\"\" class=\"wp-image-6872\" style=\"width:75px\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:spacer {\"height\":\"10px\"} -->\n<div style=\"height:10px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>ベネフィットの文章を入力してください。ベネフィットの文章を入力してください。</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":3} -->\n<h3 class=\"wp-block-heading has-text-align-center\">ベネフィット<br>その３</h3>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"10px\"} -->\n<div style=\"height:10px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:image {\"id\":6872,\"width\":\"75px\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"https://lptemp.com/dx/wp-content/uploads/note-icon.png\" alt=\"\" class=\"wp-image-6872\" style=\"width:75px\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:spacer {\"height\":\"10px\"} -->\n<div style=\"height:10px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>ベネフィットの文章を入力してください。ベネフィットの文章を入力してください。</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":3} -->\n<h3 class=\"wp-block-heading has-text-align-center\">ベネフィット<br>その４</h3>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"10px\"} -->\n<div style=\"height:10px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:image {\"id\":6872,\"width\":\"75px\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"https://lptemp.com/dx/wp-content/uploads/note-icon.png\" alt=\"\" class=\"wp-image-6872\" style=\"width:75px\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:spacer {\"height\":\"10px\"} -->\n<div style=\"height:10px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph -->\n<p>ベネフィットの文章を入力してください。ベネフィットの文章を入力してください。</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"40px\"} -->\n<div style=\"height:40px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:cover {\"overlayColor\":\"white\",\"isUserOverlayColor\":true,\"contentPosition\":\"center center\",\"isDark\":false,\"align\":\"full\",\"className\":\"is-position-center-center\"} -->\n<div class=\"wp-block-cover alignfull is-light is-position-center-center\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-white-background-color has-background-dim-100 has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:group {\"className\":\"colorful_cover_inner\",\"style\":{\"color\":{\"text\":\"#333333\"}}} -->\n<div class=\"wp-block-group colorful_cover_inner has-text-color\" style=\"color:#333333\"><!-- wp:group -->\n<div class=\"wp-block-group\"><!-- wp:spacer {\"height\":\"50px\"} -->\n<div style=\"height:50px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"className\":\"is-style-default\"} -->\n<div class=\"wp-block-group is-style-default\"><!-- wp:heading {\"textAlign\":\"center\",\"className\":\"is-style-webfont1 large-size-heading\",\"fontSize\":\"large\"} -->\n<h2 class=\"wp-block-heading has-text-align-center is-style-webfont1 large-size-heading has-large-font-size\">当サロン<span style=\"color:#0071a1\" class=\"tadv-color\">3つの特徴</span></h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"60px\"} -->\n<div style=\"height:60px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"add-relative\"} -->\n<div class=\"wp-block-group add-relative\"><!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"z-index0\"} -->\n<figure class=\"wp-block-image size-large z-index0\"><img src=\"https://lptemp.com/dx/wp-content/uploads/2021/12/pexels-ketut-subiyanto-4350090-1024x682-1.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"className\":\"mg-auto mg-negative-top50 add-relative z-index1 wid90per is-style-shadow-A label_triangle\",\"backgroundColor\":\"white\"} -->\n<div class=\"wp-block-group mg-auto mg-negative-top50 add-relative z-index1 wid90per is-style-shadow-A label_triangle has-white-background-color has-background\"><!-- wp:columns {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-center\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"100%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:100%\"><!-- wp:group {\"className\":\"line-h\"} -->\n<div class=\"wp-block-group line-h\"><!-- wp:group {\"style\":{\"color\":{\"text\":\"#91aec2\"}}} -->\n<div class=\"wp-block-group has-text-color\" style=\"color:#91aec2\"><!-- wp:paragraph {\"className\":\"is-style-webfont1 subheading-afterline\",\"fontSize\":\"medium\"} -->\n<p class=\"is-style-webfont1 subheading-afterline has-medium-font-size\"><strong><em> Feature.01</em></strong></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"className\":\"is-style-default\",\"fontSize\":\"medium\"} -->\n<h2 class=\"wp-block-heading is-style-default has-medium-font-size\">経験豊富なスタッフが対応</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:separator {\"opacity\":\"css\",\"className\":\"is-style-wide\",\"style\":{\"color\":{\"background\":\"#dfdada\"}}} -->\n<hr class=\"wp-block-separator has-text-color has-css-opacity has-background is-style-wide\" style=\"background-color:#dfdada;color:#dfdada\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"14px\"}}} -->\n<p style=\"font-size:14px\">当サロンでは経験豊富なスタッフが対応をさせていただきます。プロとして活躍するための研修と厳しい試験を突破したスタッフになりますので、安心して当サロンのサービスを受けていただけます。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"14px\"}}} -->\n<p style=\"font-size:14px\">また、定期的なスキル向上の勉強会も開いておりますので、お客様に常に最新の情報をお届けできるよう心がけております。</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"40px\"} -->\n<div style=\"height:40px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"add-relative\"} -->\n<div class=\"wp-block-group add-relative\"><!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"z-index0\"} -->\n<figure class=\"wp-block-image size-large z-index0\"><img src=\"https://lptemp.com/dx/wp-content/uploads/2021/12/pexels-ekaterina-bolovtsova-4672662-1-1024x682-1.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"className\":\"mg-auto mg-negative-top50 add-relative z-index1 wid90per is-style-shadow-A label_triangle\",\"backgroundColor\":\"white\"} -->\n<div class=\"wp-block-group mg-auto mg-negative-top50 add-relative z-index1 wid90per is-style-shadow-A label_triangle has-white-background-color has-background\"><!-- wp:columns {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-center\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"100%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:100%\"><!-- wp:group {\"className\":\"line-h\"} -->\n<div class=\"wp-block-group line-h\"><!-- wp:group {\"style\":{\"color\":{\"text\":\"#91aec2\"}}} -->\n<div class=\"wp-block-group has-text-color\" style=\"color:#91aec2\"><!-- wp:paragraph {\"className\":\"is-style-webfont1 subheading-afterline\",\"fontSize\":\"medium\"} -->\n<p class=\"is-style-webfont1 subheading-afterline has-medium-font-size\"><strong><em> </em></strong><em><strong>Feature.02</strong></em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"className\":\"is-style-default\",\"fontSize\":\"medium\"} -->\n<h2 class=\"wp-block-heading is-style-default has-medium-font-size\">口コミで多くの方に評価をいただく技術</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:separator {\"opacity\":\"css\",\"className\":\"is-style-wide\",\"style\":{\"color\":{\"background\":\"#dfdada\"}}} -->\n<hr class=\"wp-block-separator has-text-color has-css-opacity has-background is-style-wide\" style=\"background-color:#dfdada;color:#dfdada\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"14px\"}}} -->\n<p style=\"font-size:14px\">当サロンの技術は多くのお客様の非常に好評をいただいております。一時期口コミにより予約が埋まってしまうことも多くありました。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"14px\"}}} -->\n<p style=\"font-size:14px\">「全てのお客様に一流の技術で喜びの体験を」という想いをを持って全ての技術を提供させていただいております。</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"30px\"} -->\n<div style=\"height:30px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"add-relative\"} -->\n<div class=\"wp-block-group add-relative\"><!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"z-index0\"} -->\n<figure class=\"wp-block-image size-large z-index0\"><img src=\"https://lptemp.com/dx/wp-content/uploads/2021/12/pexels-andrea-piacquadio-920382-1024x682-1.jpg\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"className\":\"mg-auto mg-negative-top50 add-relative z-index1 wid90per is-style-shadow-A label_triangle\",\"backgroundColor\":\"white\"} -->\n<div class=\"wp-block-group mg-auto mg-negative-top50 add-relative z-index1 wid90per is-style-shadow-A label_triangle has-white-background-color has-background\"><!-- wp:columns {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-center\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"100%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:100%\"><!-- wp:group {\"className\":\"line-h\"} -->\n<div class=\"wp-block-group line-h\"><!-- wp:group {\"style\":{\"color\":{\"text\":\"#91aec2\"}}} -->\n<div class=\"wp-block-group has-text-color\" style=\"color:#91aec2\"><!-- wp:paragraph {\"className\":\"is-style-webfont1 subheading-afterline\",\"fontSize\":\"medium\"} -->\n<p class=\"is-style-webfont1 subheading-afterline has-medium-font-size\"><strong><em> Feature.03</em></strong></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"className\":\"is-style-default\",\"fontSize\":\"medium\"} -->\n<h2 class=\"wp-block-heading is-style-default has-medium-font-size\">サロンケア後のアフターサポートも充実</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:separator {\"opacity\":\"css\",\"className\":\"is-style-wide\",\"style\":{\"color\":{\"background\":\"#dfdada\"}}} -->\n<hr class=\"wp-block-separator has-text-color has-css-opacity has-background is-style-wide\" style=\"background-color:#dfdada;color:#dfdada\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"14px\"}}} -->\n<p style=\"font-size:14px\">サロンケアによってその時美しくなるのは当たり前です。サロンケア以降も美しさを保つために、当サロンではアフターサポートも充実しています。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"14px\"}}} -->\n<p style=\"font-size:14px\">会員専用LINEによる食事面のアドバイスや、当サロンで購入されたホームケアセットに使用アドバイス、また、現状のお肌の状態を元にどのようなホームケアのセットがおすすめかなど様々なサポートをさせていただいております。</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"40px\"} -->\n<div style=\"height:40px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"60px\"} -->\n<div style=\"height:60px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:cover {\"customOverlayColor\":\"#f3f3f3\",\"isUserOverlayColor\":true,\"contentPosition\":\"center center\",\"isDark\":false,\"align\":\"full\",\"className\":\"is-position-center-center\"} -->\n<div class=\"wp-block-cover alignfull is-light is-position-center-center\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-100 has-background-dim\" style=\"background-color:#f3f3f3\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:group {\"className\":\"colorful_Heading_New_Basic is-style-default\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"800px\"}} -->\n<div class=\"wp-block-group colorful_Heading_New_Basic is-style-default\"><!-- wp:spacer {\"height\":\"40px\"} -->\n<div style=\"height:40px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"className\":\"large-size-heading is-style-default\"} -->\n<h2 class=\"wp-block-heading has-text-align-center large-size-heading is-style-default\">このサービスを受けると<br>こんな効果を得られます</h2>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"40px\"} -->\n<div style=\"height:40px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:cover {\"customOverlayColor\":\"white\",\"isUserOverlayColor\":true,\"contentPosition\":\"center center\",\"isDark\":false,\"align\":\"center\",\"className\":\"is-position-center-center has-white-background-color colorful-frame1\",\"style\":{\"border\":{\"radius\":\"0px\"}}} -->\n<div class=\"wp-block-cover aligncenter is-light is-position-center-center has-white-background-color colorful-frame1\" style=\"border-radius:0px\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-100 has-background-dim\" style=\"background-color:white\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:group {\"style\":{\"color\":{\"text\":\"#333333\",\"background\":\"#fafafa\"},\"border\":{\"radius\":\"0px\"}}} -->\n<div class=\"wp-block-group has-text-color has-background\" style=\"border-radius:0px;color:#333333;background-color:#fafafa\"><!-- wp:list {\"className\":\"is-style-chk-A3\"} -->\n<ul class=\"wp-block-list is-style-chk-A3\"><!-- wp:list-item -->\n<li>ここにサービスを受けることで得られる効果やベネフィットを記載してください。ここにサービスを受けることで得られる効果やベネフィットを記載してください。</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>ここにサービスを受けることで得られる効果やベネフィットを記載してください。ここにサービスを受けることで得られる効果やベネフィットを記載してください。</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>ここにサービスを受けることで得られる効果やベネフィットを記載してください。ここにサービスを受けることで得られる効果やベネフィットを記載してください。</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>ここにサービスを受けることで得られる効果やベネフィットを記載してください。ここにサービスを受けることで得られる効果やベネフィットを記載してください。</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:spacer {\"height\":\"40px\"} -->\n<div style=\"height:40px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:cover {\"url\":\"https://lptemp.com/dx/wp-content/uploads/wall4.png\",\"id\":3859,\"isRepeated\":true,\"dimRatio\":50,\"overlayColor\":\"white\",\"isUserOverlayColor\":true,\"contentPosition\":\"center center\",\"isDark\":false,\"align\":\"full\"} -->\n<div class=\"wp-block-cover alignfull is-light is-repeated\"><div class=\"wp-block-cover__image-background wp-image-3859 is-repeated\" style=\"background-position:50% 50%;background-image:url(https://lptemp.com/dx/wp-content/uploads/wall4.png)\"></div><span aria-hidden=\"true\" class=\"wp-block-cover__background has-white-background-color has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:group {\"className\":\"colorful_cover_inner\",\"style\":{\"color\":{\"text\":\"#333333\"}}} -->\n<div class=\"wp-block-group colorful_cover_inner has-text-color\" style=\"color:#333333\"><!-- wp:group -->\n<div class=\"wp-block-group\"><!-- wp:spacer {\"height\":\"51px\"} -->\n<div style=\"height:51px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"className\":\"colorful_Heading_New_Basic\"} -->\n<div class=\"wp-block-group colorful_Heading_New_Basic\"><!-- wp:heading {\"textAlign\":\"center\",\"className\":\"large-size-heading\",\"style\":{\"typography\":{\"letterSpacing\":\"-1px\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center large-size-heading\" style=\"letter-spacing:-1px\">こんなことにお悩みの方は<br>お料理代行をオススメしてます♪</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"61px\"} -->\n<div style=\"height:61px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {\"className\":\"gap-0 mg-0\"} -->\n<div class=\"wp-block-columns gap-0 mg-0\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:cover {\"customOverlayColor\":\"#f2e6cc\",\"isUserOverlayColor\":true,\"isDark\":false} -->\n<div class=\"wp-block-cover is-light\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-100 has-background-dim\" style=\"background-color:#f2e6cc\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:image {\"id\":3862,\"sizeSlug\":\"medium\",\"linkDestination\":\"none\",\"align\":\"center\",\"className\":\"is-style-rounded\"} -->\n<figure class=\"wp-block-image aligncenter size-medium is-style-rounded\"><img src=\"https://lptemp.com/dx/wp-content/uploads/cook01-300x300.jpg\" alt=\"\" class=\"wp-image-3862\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"fontSize\":\"medium\"} -->\n<h3 class=\"wp-block-heading has-text-align-center has-medium-font-size\">毎日の献立に悩んでいる</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>日々の献立を考えることが大変で、いつもワンパターンな食事になってしまっている</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:cover {\"customOverlayColor\":\"#f4f4f4\",\"isUserOverlayColor\":true,\"isDark\":false} -->\n<div class=\"wp-block-cover is-light\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-100 has-background-dim\" style=\"background-color:#f4f4f4\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:image {\"id\":3863,\"sizeSlug\":\"medium\",\"linkDestination\":\"none\",\"align\":\"center\",\"className\":\"is-style-rounded\"} -->\n<figure class=\"wp-block-image aligncenter size-medium is-style-rounded\"><img src=\"https://lptemp.com/dx/wp-content/uploads/eat01-300x300.jpg\" alt=\"\" class=\"wp-image-3863\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"fontSize\":\"medium\"} -->\n<h3 class=\"wp-block-heading has-text-align-center has-medium-font-size\">栄養バランスが取れてるか心配</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>いつも同じようなメニューが続いていることで、栄養バランスが取れてないことに不安を感じる</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:columns {\"className\":\"gap-0 flx_direc_revs\"} -->\n<div class=\"wp-block-columns gap-0 flx_direc_revs\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:cover {\"customOverlayColor\":\"#f4f4f4\",\"isUserOverlayColor\":true,\"isDark\":false} -->\n<div class=\"wp-block-cover is-light\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-100 has-background-dim\" style=\"background-color:#f4f4f4\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:image {\"id\":3864,\"sizeSlug\":\"medium\",\"linkDestination\":\"none\",\"align\":\"center\",\"className\":\"is-style-rounded\"} -->\n<figure class=\"wp-block-image aligncenter size-medium is-style-rounded\"><img src=\"https://lptemp.com/dx/wp-content/uploads/cook02-300x300.jpg\" alt=\"\" class=\"wp-image-3864\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"fontSize\":\"medium\"} -->\n<h3 class=\"wp-block-heading has-text-align-center has-medium-font-size\">普段とは違う食事を楽しみたい</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>新型コロナが発生して以降、外食に行きにくくなったので、自宅でプロの味を楽しみたい。</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:cover {\"customOverlayColor\":\"#f2e6cc\",\"isUserOverlayColor\":true,\"isDark\":false} -->\n<div class=\"wp-block-cover is-light\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-100 has-background-dim\" style=\"background-color:#f2e6cc\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:image {\"id\":3865,\"sizeSlug\":\"medium\",\"linkDestination\":\"none\",\"align\":\"center\",\"className\":\"is-style-rounded\"} -->\n<figure class=\"wp-block-image aligncenter size-medium is-style-rounded\"><img src=\"https://lptemp.com/dx/wp-content/uploads/family01-300x300.jpg\" alt=\"\" class=\"wp-image-3865\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"fontSize\":\"medium\"} -->\n<h3 class=\"wp-block-heading has-text-align-center has-medium-font-size\">たまには食事づくりから解放されたい</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>毎日料理を作る時間を、たまには家族や自分のために使いたいと考えている</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"30px\"} -->\n<div style=\"height:30px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:cover {\"url\":\"https://lptemp.com/dx/wp-content/uploads/crosses.png\",\"id\":3868,\"isRepeated\":true,\"dimRatio\":0,\"contentPosition\":\"center center\",\"isDark\":false,\"align\":\"full\"} -->\n<div class=\"wp-block-cover alignfull is-light is-repeated\"><div class=\"wp-block-cover__image-background wp-image-3868 is-repeated\" style=\"background-position:50% 50%;background-image:url(https://lptemp.com/dx/wp-content/uploads/crosses.png)\"></div><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-0 has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:spacer {\"height\":\"50px\"} -->\n<div style=\"height:50px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"className\":\"colorful_Heading_New_Basic is-style-suptext\"} -->\n<div class=\"wp-block-group 