(23, 1, '2026-01-31 18:19:05', '2026-01-31 09:19:05', '.rehap-sticky-header {\n  position: sticky;\n  top: 0;\n  z-index: 9999;\n  background: #ffffff;\n  box-shadow: 0 2px 8px rgba(0,0,0,0.08);\n}\n', 'colorful-theme', '', 'publish', 'closed', 'closed', '', 'colorful-theme', '', '', '2026-01-31 18:45:44', '2026-01-31 09:45:44', '', 0, 'https://relybit.co.jp/rehap/lp/colorful-theme/', 0, 'custom_css', '', 0),
(24, 1, '2026-01-31 18:19:05', '2026-01-31 09:19:05', '/* ヘッダーメニューを横並び */\n.site-header nav ul {\n  display: flex;\n  align-items: center;\n}\n\n/* ロゴを左に固定 */\n.site-header .header-logo {\n  margin-right: auto;\n}\n\n.site-header .header-logo img {\n  display: block;\n}\n', 'colorful-theme', '', 'inherit', 'closed', 'closed', '', '23-revision-v1', '', '', '2026-01-31 18:19:05', '2026-01-31 09:19:05', '', 23, 'https://relybit.co.jp/rehap/lp/?p=24', 0, 'revision', '', 0),
(28, 1, '2026-01-31 18:40:07', '2026-01-31 09:40:07', '/* 疑似ヘッダー固定（スクロール追従） */\n.rehap-sticky-header {\n  position: fixed;\n  top: 0;\n  left: 0;\n  width: 100%;\n  background: #fff;\n  z-index: 9999;\n  padding: 10px 0;\n  box-shadow: 0 1px 4px rgba(0,0,0,0.1);\n}\n\n/* 横並び */\n.rehap-sticky-header .wp-block-group {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  max-width: 1200px;\n  margin: 0 auto;\n}\n\n/* CTAボタン */\n.rehap-sticky-header .wp-block-button a {\n  padding: 10px 18px;\n  border-radius: 999px;\n  font-weight: 700;\n  text-decoration: none;\n  margin-left: 8px;\n}\n.rehap-sticky-header .wp-block-button:nth-child(2) a {\n  background: #ff4d2d;\n  color: #fff;\n}\n.rehap-sticky-header .wp-block-button:nth-child(1) a {\n  border: 2px solid #ff4d2d;\n  color: #ff4d2d;\n  background: #fff;\n}\n', 'colorful-theme', '', 'inherit', 'closed', 'closed', '', '23-revision-v1', '', '', '2026-01-31 18:40:07', '2026-01-31 09:40:07', '', 23, 'https://relybit.co.jp/rehap/lp/?p=28', 0, 'revision', '', 0);
