(191, 2, '2026-03-02 06:02:17', '2026-03-01 21:02:17', '<!-- wp:group {\"align\":\"full\",\"className\":\"vk_block-margin-0\\u002d\\u002dmargin-top\",\"style\":{\"color\":{\"background\":\"#ececec\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull vk_block-margin-0--margin-top has-background\" style=\"background-color:#ececec\"><!-- wp:vk-blocks/spacer {\"spaceType\":\"height\"} -->\n<div class=\"wp-block-vk-blocks-spacer vk_spacer vk_spacer-type-height\"><div class=\"vk_block-margin-md--height\"></div></div>\n<!-- /wp:vk-blocks/spacer -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"vk_block-margin-xxs\\u002d\\u002dmargin-bottom\"} -->\n<p class=\"has-text-align-center vk_block-margin-xxs--margin-bottom\">まずは仕組みや活用方法のご相談だけでも可能です！</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:vk-blocks/button {\"buttonSize\":\"lg\",\"buttonEffect\":\"shine\",\"buttonAlign\":\"center\",\"fontAwesomeIconBefore\":\"\\u003ci class=\\u0022fa-regular fa-envelope\\u0022\\u003e\\u003c/i\\u003e\",\"blockId\":\"01fac02e-7152-46f7-b313-78af68bfda77\"} -->\n<div class=\"wp-block-vk-blocks-button vk_button vk_button-color-custom vk_button-align-center is-style-shine\"><a class=\"vk_button_link btn has-background has-vk-color-primary-background-color btn-lg\" role=\"button\" aria-pressed=\"true\" rel=\"noopener\"><div class=\"vk_button_link_caption\"><i class=\"fa-regular fa-envelope vk_button_link_before\"></i><span class=\"vk_button_link_txt\"><strong>REHAPについて問い合わせる</strong></span></div></a></div>\n<!-- /wp:vk-blocks/button -->\n\n<!-- wp:vk-blocks/spacer {\"spaceType\":\"height\"} -->\n<div class=\"wp-block-vk-blocks-spacer vk_spacer vk_spacer-type-height\"><div class=\"vk_block-margin-md--height\"></div></div>\n<!-- /wp:vk-blocks/spacer --></div>\n<!-- /wp:group -->\n\n<!-- wp:cover {\"url\":\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/02/rehap_img_black-1024x517.webp\",\"id\":112,\"dimRatio\":70,\"customOverlayColor\":\"#942b2b\",\"isUserOverlayColor\":true,\"sizeSlug\":\"large\",\"align\":\"full\",\"className\":\"vk_block-margin-0\\u002d\\u002dmargin-bottom\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-cover alignfull vk_block-margin-0--margin-bottom\"><img class=\"wp-block-cover__image-background wp-image-112 size-large\" alt=\"\" src=\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/02/rehap_img_black-1024x517.webp\" data-object-fit=\"cover\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-70 has-background-dim\" style=\"background-color:#942b2b\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"タイトルを入力...\",\"fontSize\":\"large\"} -->\n<p class=\"has-text-align-center has-large-font-size\"></p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:image {\"id\":113,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"align\":\"full\",\"className\":\"vk_block-margin-0\\u002d\\u002dmargin-top vk_block-margin-0\\u002d\\u002dmargin-bottom\"} -->\n<figure class=\"wp-block-image alignfull size-large vk_block-margin-0--margin-top vk_block-margin-0--margin-bottom\"><img src=\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/02/rehap_img_4-1024x174.webp\" alt=\"\" class=\"wp-image-113\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#f9f9f9\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-background\" style=\"background-color:#f9f9f9\"><!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"vk_block-margin-lg\\u002d\\u002dmargin-bottom\",\"fontSize\":\"large\"} -->\n<p class=\"has-text-align-center vk_block-margin-lg--margin-bottom has-large-font-size\"><strong>そんな店舗経営の悩みに</strong><br><strong>信頼を活かす収益モデル、REHAP</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph -->\n<p><strong>リアル店舗 × 成果報酬</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>REHAP（リハップ）は、<br>整体院・サロン・ジム等のさまざまな<br>実店舗ビジネスと信頼できる商品・サービスをつなぐ、成果報酬型パートナーサービスです。</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":114,\"width\":\"234px\",\"height\":\"auto\",\"aspectRatio\":\"0.9116499915211125\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/02/rehap_illust.webp\" alt=\"\" class=\"wp-image-114\" style=\"aspect-ratio:0.9116499915211125;width:234px;height:auto\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"vk_block-margin-xl\\u002d\\u002dmargin-top\"} -->\n<p class=\"has-text-align-center vk_block-margin-xl--margin-top\">REHAPは、単に商品を販売する仕組みではありません。<br>店舗の信頼・価値を守りながら、無理なく収益を生み出すことを目的として設計されています。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"vk_block-margin-0\\u002d\\u002dmargin-bottom\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vk-color-primary\"}}}},\"textColor\":\"vk-color-primary\",\"fontSize\":\"huge\"} -->\n<p class=\"has-text-align-center vk_block-margin-0--margin-bottom has-vk-color-primary-color has-text-color has-link-color has-huge-font-size\"><strong>サービスの仕組み</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vk-color-primary\"}}}},\"textColor\":\"vk-color-primary\"} -->\n<p class=\"has-text-align-center has-vk-color-primary-color has-text-color has-link-color\"><strong>Service structure</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":122,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full\"><img src=\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/02/rehap_illust_図.webp\" alt=\"\" class=\"wp-image-122\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"vk_block-margin-md\\u002d\\u002dmargin-bottom vk_block-margin-md\\u002d\\u002dmargin-top\"} -->\n<p class=\"has-text-align-center vk_block-margin-md--margin-bottom vk_block-margin-md--margin-top\"><strong>QRコードに置くだけで収益が生まれる理由</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"vk_block-margin-xl\\u002d\\u002dmargin-bottom\"} -->\n<p class=\"has-text-align-center vk_block-margin-xl--margin-bottom\">従来の「成果報酬型広告＝アフィリエイト」はWebメディアやSNSが中心でしたが、<br>REHAPでは、「リアル店舗 × 成果報酬」という新しい形で、<br>店舗の来店客・既存顧客・ファン層を活かした収益化を実現します。<br>REHAPは、単に商品を販売する仕組みではありません。<br>店舗の信頼・価値を守りながら、無理なく収益を生み出すことを目的として設計されています。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\"><strong>REHAPを導入した店舗では</strong><br><strong>「新しい業務を増やさずに、副収益を得られる環境」が生まれています。</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#f9f9f9\"},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-background\" style=\"background-color:#f9f9f9;padding-top:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50)\"><!-- wp:vk-blocks/spacer {\"pc\":120,\"tablet\":50,\"mobile\":40,\"spaceSize\":\"custom\"} -->\n<div class=\"wp-block-vk-blocks-spacer vk_spacer\"><div class=\"vk_spacer-display-pc\" style=\"margin-top:120px\"></div><div class=\"vk_spacer-display-tablet\" style=\"margin-top:50px\"></div><div class=\"vk_spacer-display-mobile\" style=\"margin-top:40px\"></div></div>\n<!-- /wp:vk-blocks/spacer -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"vk_block-margin-0\\u002d\\u002dmargin-bottom\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vk-color-primary\"}}}},\"textColor\":\"vk-color-primary\",\"fontSize\":\"huge\"} -->\n<p class=\"has-text-align-center vk_block-margin-0--margin-bottom has-vk-color-primary-color has-text-color has-link-color has-huge-font-size\"><strong>導入メリット</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vk-color-primary\"}}}},\"textColor\":\"vk-color-primary\"} -->\n<p class=\"has-text-align-center has-vk-color-primary-color has-text-color has-link-color\"><strong>Benefits</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:vk-blocks/spacer {\"pc\":50,\"spaceSize\":\"custom\"} -->\n<div class=\"wp-block-vk-blocks-spacer vk_spacer\"><div class=\"vk_spacer-display-pc\" style=\"margin-top:50px\"></div><div class=\"vk_spacer-display-tablet\" style=\"margin-top:30px\"></div><div class=\"vk_spacer-display-mobile\" style=\"margin-top:20px\"></div></div>\n<!-- /wp:vk-blocks/spacer -->\n\n<!-- wp:columns {\"style\":{\"border\":{\"radius\":{\"topLeft\":\"20px\",\"topRight\":\"20px\",\"bottomLeft\":\"20px\",\"bottomRight\":\"20px\"}},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"shadow\":\"var:preset|shadow|natural\"},\"backgroundColor\":\"white\"} -->\n<div class=\"wp-block-columns has-white-background-color has-background\" style=\"border-top-left-radius:20px;border-top-right-radius:20px;border-bottom-left-radius:20px;border-bottom-right-radius:20px;margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50);box-shadow:var(--wp--preset--shadow--natural)\"><!-- wp:column {\"width\":\"20%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:20%\"><!-- wp:image {\"id\":123,\"width\":\"150px\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/02/2.webp\" alt=\"\" class=\"wp-image-123\" style=\"width:150px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"80%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:80%\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vk-color-primary\"}}}},\"textColor\":\"vk-color-primary\",\"fontSize\":\"large\"} -->\n<p class=\"has-vk-color-primary-color has-text-color has-link-color has-large-font-size\"><strong>01｜初期費用・固定費ゼロで副収益を得られる</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>REHAPでは、店舗で商品やサービスを紹介することで、成果に応じた報酬が発生します。成果報酬型のため、初期費用や月額費用、在庫リスクは一切ありません。<br>登録案件の中から、店舗に合った商品・サービスを自由に選べます。</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:vk-blocks/spacer {\"spaceType\":\"height\",\"pc\":50,\"spaceSize\":\"custom\"} -->\n<div class=\"wp-block-vk-blocks-spacer vk_spacer\"><div class=\"vk_spacer-display-pc\" style=\"height:50px\"></div><div class=\"vk_spacer-display-tablet\" style=\"height:30px\"></div><div class=\"vk_spacer-display-mobile\" style=\"height:20px\"></div></div>\n<!-- /wp:vk-blocks/spacer -->\n\n<!-- wp:columns {\"className\":\"is-vk-row-reverse\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"20px\",\"topRight\":\"20px\",\"bottomLeft\":\"20px\",\"bottomRight\":\"20px\"}},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"shadow\":\"var:preset|shadow|natural\"},\"backgroundColor\":\"white\",\"reverse\":true} -->\n<div class=\"wp-block-columns is-vk-row-reverse has-white-background-color has-background\" style=\"border-top-left-radius:20px;border-top-right-radius:20px;border-bottom-left-radius:20px;border-bottom-right-radius:20px;margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50);box-shadow:var(--wp--preset--shadow--natural)\"><!-- wp:column {\"width\":\"20%\",\"style\":{\"shadow\":\"none\"}} -->\n<div class=\"wp-block-column\" style=\"box-shadow:none;flex-basis:20%\"><!-- wp:image {\"id\":126,\"width\":\"150px\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/02/3.webp\" alt=\"\" class=\"wp-image-126\" style=\"width:150px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"80%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:80%\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vk-color-primary\"}}}},\"textColor\":\"vk-color-primary\",\"fontSize\":\"large\"} -->\n<p class=\"has-vk-color-primary-color has-text-color has-link-color has-large-font-size\"><strong><strong>02｜スタッフ評価・モチベーション向上</strong></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>スタッフごとに販売した件数を可視化していただくことで、スタッフ評価やインセンティブ設計に活用できます。<br>実業務で売上が伸び悩んでいるスタッフも、REHAPでの収益をプラスオンして評価していただけます。</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:vk-blocks/spacer {\"spaceType\":\"height\",\"pc\":50,\"spaceSize\":\"custom\"} -->\n<div class=\"wp-block-vk-blocks-spacer vk_spacer\"><div class=\"vk_spacer-display-pc\" style=\"height:50px\"></div><div class=\"vk_spacer-display-tablet\" style=\"height:30px\"></div><div class=\"vk_spacer-display-mobile\" style=\"height:20px\"></div></div>\n<!-- /wp:vk-blocks/spacer -->\n\n<!-- wp:columns {\"style\":{\"border\":{\"radius\":{\"topLeft\":\"20px\",\"topRight\":\"20px\",\"bottomLeft\":\"20px\",\"bottomRight\":\"20px\"}},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"shadow\":\"var:preset|shadow|natural\"},\"backgroundColor\":\"white\"} -->\n<div class=\"wp-block-columns has-white-background-color has-background\" style=\"border-top-left-radius:20px;border-top-right-radius:20px;border-bottom-left-radius:20px;border-bottom-right-radius:20px;margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50);box-shadow:var(--wp--preset--shadow--natural)\"><!-- wp:column {\"width\":\"20%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:20%\"><!-- wp:image {\"id\":127,\"width\":\"150px\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/02/4.webp\" alt=\"\" class=\"wp-image-127\" style=\"width:150px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"80%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:80%\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vk-color-primary\"}}}},\"textColor\":\"vk-color-primary\",\"fontSize\":\"large\"} -->\n<p class=\"has-vk-color-primary-color has-text-color has-link-color has-large-font-size\"><strong><strong>03｜自社サービスの売上拡大にも活用できる</strong></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>REHAPでは、店舗様ご自身のサービスを掲載し、Webメディアで紹介することも可能です。<br>比較記事やランキング記事などに掲載され、成果が発生した場合のみ広告費が発生する成果報酬型のため、費用リスクを抑えて集客が行えます。</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:vk-blocks/spacer {\"spaceType\":\"height\",\"spaceSize\":\"large\"} -->\n<div class=\"wp-block-vk-blocks-spacer vk_spacer vk_spacer-type-height\"><div class=\"vk_block-margin-lg--height\"></div></div>\n<!-- /wp:vk-blocks/spacer -->\n\n<!-- wp:columns {\"className\":\"is-vk-row-reverse\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"20px\",\"topRight\":\"20px\",\"bottomLeft\":\"20px\",\"bottomRight\":\"20px\"}},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"shadow\":\"var:preset|shadow|natural\"},\"backgroundColor\":\"white\",\"reverse\":true} -->\n<div class=\"wp-block-columns is-vk-row-reverse has-white-background-color has-background\" style=\"border-top-left-radius:20px;border-top-right-radius:20px;border-bottom-left-radius:20px;border-bottom-right-radius:20px;margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50);box-shadow:var(--wp--preset--shadow--natural)\"><!-- wp:column {\"width\":\"20%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:20%\"><!-- wp:image {\"id\":128,\"width\":\"150px\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/02/5.webp\" alt=\"\" class=\"wp-image-128\" style=\"width:150px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"80%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:80%\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vk-color-primary\"}}}},\"textColor\":\"vk-color-primary\",\"fontSize\":\"large\"} -->\n<p class=\"has-vk-color-primary-color has-text-color has-link-color has-large-font-size\"><strong><strong><strong>04｜公式サイト・メディアでの無料掲載</strong></strong></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>REHAPの公式サイトに提携店舗様を記載させていただきます。<br>また、導入から3ヶ月以上が経過した店舗様は、弊社が運営するメディアにも紹介記事を掲載させていただきます。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"fontSize\":\"small\"} -->\n<p class=\"has-small-font-size\">※掲載が不要の場合は担当者にご連絡ください。<br>※掲載タイミングはREHAPのシステム状況や対応スケジュールを加味して調整させていただきます。</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:vk-blocks/spacer {\"spaceType\":\"height\",\"pc\":50,\"spaceSize\":\"custom\"} -->\n<div class=\"wp-block-vk-blocks-spacer vk_spacer\"><div class=\"vk_spacer-display-pc\" style=\"height:50px\"></div><div class=\"vk_spacer-display-tablet\" style=\"height:30px\"></div><div class=\"vk_spacer-display-mobile\" style=\"height:20px\"></div></div>\n<!-- /wp:vk-blocks/spacer -->\n\n<!-- wp:columns {\"style\":{\"border\":{\"radius\":{\"topLeft\":\"20px\",\"topRight\":\"20px\",\"bottomLeft\":\"20px\",\"bottomRight\":\"20px\"}},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"shadow\":\"var:preset|shadow|natural\"},\"backgroundColor\":\"white\"} -->\n<div class=\"wp-block-columns has-white-background-color has-background\" style=\"border-top-left-radius:20px;border-top-right-radius:20px;border-bottom-left-radius:20px;border-bottom-right-radius:20px;margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50);box-shadow:var(--wp--preset--shadow--natural)\"><!-- wp:column {\"width\":\"20%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:20%\"><!-- wp:image {\"id\":129,\"width\":\"150px\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/02/6.webp\" alt=\"\" class=\"wp-image-129\" style=\"width:150px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"80%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:80%\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vk-color-primary\"}}}},\"textColor\":\"vk-color-primary\",\"fontSize\":\"large\"} -->\n<p class=\"has-vk-color-primary-color has-text-color has-link-color has-large-font-size\"><strong><strong><strong>05｜交流会での無料PR掲出権</strong></strong></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>運営会社リリビットが主催する交流会やイベントにおいて、店舗様のチラシやパンフレットを掲出していただくことが可能です。<br>直接他事業者にアプローチできるため、販路拡大や認知向上が期待できます。</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:vk-blocks/spacer {\"spaceType\":\"height\",\"pc\":50,\"spaceSize\":\"custom\"} -->\n<div class=\"wp-block-vk-blocks-spacer vk_spacer\"><div class=\"vk_spacer-display-pc\" style=\"height:50px\"></div><div class=\"vk_spacer-display-tablet\" style=\"height:30px\"></div><div class=\"vk_spacer-display-mobile\" style=\"height:20px\"></div></div>\n<!-- /wp:vk-blocks/spacer -->\n\n<!-- wp:columns {\"className\":\"is-vk-row-reverse\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"20px\",\"topRight\":\"20px\",\"bottomLeft\":\"20px\",\"bottomRight\":\"20px\"}},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"shadow\":\"var:preset|shadow|natural\"},\"backgroundColor\":\"white\",\"reverse\":true} -->\n<div class=\"wp-block-columns is-vk-row-reverse has-white-background-color has-background\" style=\"border-top-left-radius:20px;border-top-right-radius:20px;border-bottom-left-radius:20px;border-bottom-right-radius:20px;margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50);box-shadow:var(--wp--preset--shadow--natural)\"><!-- wp:column {\"width\":\"20%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:20%\"><!-- wp:image {\"id\":130,\"width\":\"150px\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/02/7.webp\" alt=\"\" class=\"wp-image-130\" style=\"width:150px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"80%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:80%\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vk-color-primary\"}}}},\"textColor\":\"vk-color-primary\",\"fontSize\":\"large\"} -->\n<p class=\"has-vk-color-primary-color has-text-color has-link-color has-large-font-size\"><strong><strong><strong><strong>06｜Webマーケティングの無料相談</strong></strong></strong></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>REHAPをご導入いただいた店舗様は、弊社にてWebマーケティング全般についての無料相談をご利用いただくことが可能です。<br>売上拡大・集客・採用・認知向上といったさまざまなお悩みをご相談いただけます。</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:vk-blocks/spacer {\"spaceType\":\"height\",\"pc\":50,\"spaceSize\":\"custom\"} -->\n<div class=\"wp-block-vk-blocks-spacer vk_spacer\"><div class=\"vk_spacer-display-pc\" style=\"height:50px\"></div><div class=\"vk_spacer-display-tablet\" style=\"height:30px\"></div><div class=\"vk_spacer-display-mobile\" style=\"height:20px\"></div></div>\n<!-- /wp:vk-blocks/spacer -->\n\n<!-- wp:columns {\"className\":\"is-vk-row-reverse\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"20px\",\"topRight\":\"20px\",\"bottomLeft\":\"20px\",\"bottomRight\":\"20px\"}},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"shadow\":\"var:preset|shadow|natural\"},\"backgroundColor\":\"white\",\"reverse\":true} -->\n<div class=\"wp-block-columns is-vk-row-reverse has-white-background-color has-background\" style=\"border-top-left-radius:20px;border-top-right-radius:20px;border-bottom-left-radius:20px;border-bottom-right-radius:20px;margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50);box-shadow:var(--wp--preset--shadow--natural)\"><!-- wp:column {\"width\":\"100%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:100%\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vk-color-primary\"}}}},\"textColor\":\"vk-color-primary\",\"fontSize\":\"large\"} -->\n<p class=\"has-vk-color-primary-color has-text-color has-link-color has-large-font-size\"><strong><strong><strong><strong><strong>07｜REHAP認定証の付与</strong></strong></strong></strong></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>REHAPを導入していただいた店舗様に、REHAP認定証をお渡しいたします。</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:vk-blocks/spacer {\"pc\":120,\"tablet\":50,\"mobile\":40,\"spaceSize\":\"custom\"} -->\n<div class=\"wp-block-vk-blocks-spacer vk_spacer\"><div class=\"vk_spacer-display-pc\" style=\"margin-top:120px\"></div><div class=\"vk_spacer-display-tablet\" style=\"margin-top:50px\"></div><div class=\"vk_spacer-display-mobile\" style=\"margin-top:40px\"></div></div>\n<!-- /wp:vk-blocks/spacer --></div>\n<!-- /wp:group -->\n\n<!-- wp:vk-blocks/spacer {\"pc\":120,\"tablet\":50,\"mobile\":40,\"spaceSize\":\"custom\"} -->\n<div class=\"wp-block-vk-blocks-spacer vk_spacer\"><div class=\"vk_spacer-display-pc\" style=\"margin-top:120px\"></div><div class=\"vk_spacer-display-tablet\" style=\"margin-top:50px\"></div><div class=\"vk_spacer-display-mobile\" style=\"margin-top:40px\"></div></div>\n<!-- /wp:vk-blocks/spacer -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"vk_block-margin-0\\u002d\\u002dmargin-bottom\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vk-color-primary\"}}}},\"textColor\":\"vk-color-primary\",\"fontSize\":\"huge\"} -->\n<p class=\"has-text-align-center vk_block-margin-0--margin-bottom has-vk-color-primary-color has-text-color has-link-color has-huge-font-size\"><strong>導入事例</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"vk_block-margin-lg\\u002d\\u002dmargin-bottom\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vk-color-primary\"}}}},\"textColor\":\"vk-color-primary\"} -->\n<p class=\"has-text-align-center vk_block-margin-lg--margin-bottom has-vk-color-primary-color has-text-color has-link-color\"><strong>Use Cases</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"vk_block-margin-lg\\u002d\\u002dmargin-bottom\"} -->\n<p class=\"has-text-align-center vk_block-margin-lg--margin-bottom\">REHAP（リハップ）は、さまざまな実店舗ビジネスで導入されています。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:columns {\"isStackedOnMobile\":false,\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|40\",\"left\":\"var:preset|spacing|40\",\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|40\"}}}} -->\n<div class=\"wp-block-columns is-not-stacked-on-mobile\" style=\"padding-top:var(--wp--preset--spacing--40);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--40);padding-left:var(--wp--preset--spacing--40)\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":183,\"width\":\"200px\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full is-resized\"><img src=\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/03/rehap_shops8.webp\" alt=\"\" class=\"wp-image-183\" style=\"width:200px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":184,\"width\":\"200px\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full is-resized\"><img src=\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/03/rehap_shops9.webp\" alt=\"\" class=\"wp-image-184\" style=\"width:200px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":185,\"width\":\"200px\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full is-resized\"><img src=\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/03/rehap_shops10.webp\" alt=\"\" class=\"wp-image-185\" style=\"width:200px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":186,\"width\":\"200px\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full is-resized\"><img src=\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/03/rehap_shops11.webp\" alt=\"\" class=\"wp-image-186\" style=\"width:200px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:columns {\"isStackedOnMobile\":false,\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|40\",\"left\":\"var:preset|spacing|40\",\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|40\"}}}} -->\n<div class=\"wp-block-columns is-not-stacked-on-mobile\" style=\"padding-top:var(--wp--preset--spacing--40);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--40);padding-left:var(--wp--preset--spacing--40)\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":187,\"width\":\"200px\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full is-resized\"><img src=\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/03/rehap_shops12.webp\" alt=\"\" class=\"wp-image-187\" style=\"width:200px\"/></figure>\n<!-- /wp:image 