"id\":145,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/02/REHAPさん_スマホ1-1024x549.webp\" alt=\"\" class=\"wp-image-145\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":146,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"vk_block-margin-0\\u002d\\u002dmargin-bottom\"} -->\n<figure class=\"wp-block-image size-large vk_block-margin-0--margin-bottom\"><img src=\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/02/REHAPさん_スマホ2-1024x549.webp\" alt=\"\" class=\"wp-image-146\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"blockGap\":\"0px\",\"padding\":{\"right\":\"0px\",\"left\":\"0px\"}}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"padding-right:0px;padding-left:0px\"><!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"0px\",\"left\":\"0px\"}},\"layout\":{\"selfStretch\":\"fit\",\"flexSize\":null}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group\" style=\"padding-right:0px;padding-left:0px\"></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:cover {\"url\":\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/02/rehap_img_black-1024x517.webp\",\"id\":112,\"dimRatio\":70,\"customOverlayColor\":\"#942b2b\",\"isUserOverlayColor\":true,\"sizeSlug\":\"large\",\"align\":\"full\",\"className\":\"vk_block-margin-0\\u002d\\u002dmargin-bottom vk_block-margin-0\\u002d\\u002dmargin-top\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-cover alignfull vk_block-margin-0--margin-bottom vk_block-margin-0--margin-top\"><img class=\"wp-block-cover__image-background wp-image-112 size-large\" alt=\"\" src=\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/02/rehap_img_black-1024x517.webp\" data-object-fit=\"cover\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-70 has-background-dim\" style=\"background-color:#942b2b\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\"><strong>無理な営業や導入のご提案は行っていません。</strong><br><strong>まずは仕組みや活用方法のご相談だけでも可能です。</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:vk-blocks/button {\"buttonSize\":\"lg\",\"buttonEffect\":\"shine\",\"buttonColor\":\"custom\",\"buttonTextColorCustom\":\"vk-color-primary\",\"buttonColorCustom\":\"#fefefe\",\"buttonAlign\":\"wide\",\"blockId\":\"37ad5910-5273-433d-b1b6-3cd717916530\"} -->\n<div class=\"wp-block-vk-blocks-button vk_button vk_button-color-custom vk_button-37ad5910-5273-433d-b1b6-3cd717916530 vk_button-align-wide is-style-shine\"><a class=\"vk_button_link btn has-background btn has-text-color has-vk-color-primary-color btn-lg\" role=\"button\" aria-pressed=\"true\" rel=\"noopener\"><div class=\"vk_button_link_caption\"><span class=\"vk_button_link_txt\"><strong>REHAPについて問い合わせる</strong></span></div></a></div><style type=\"text/css\">.vk_button-37ad5910-5273-433d-b1b6-3cd717916530 .has-background {\n				background-color: #fefefe;\n				border: 1px solid #fefefe;\n			} </style>\n<!-- /wp:vk-blocks/button --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:vk-blocks/spacer {\"pc\":120,\"tablet\":50,\"mobile\":40,\"spaceSize\":\"custom\"} -->\n<div class=\"wp-block-vk-blocks-spacer vk_spacer\"><div class=\"vk_spacer-display-pc\" style=\"margin-top:120px\"></div><div class=\"vk_spacer-display-tablet\" style=\"margin-top:50px\"></div><div class=\"vk_spacer-display-mobile\" style=\"margin-top:40px\"></div></div>\n<!-- /wp:vk-blocks/spacer -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"vk_block-margin-0\\u002d\\u002dmargin-bottom\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vk-color-primary\"}}}},\"textColor\":\"vk-color-primary\",\"fontSize\":\"huge\"} -->\n<p class=\"has-text-align-center vk_block-margin-0--margin-bottom has-vk-color-primary-color has-text-color has-link-color has-huge-font-size\"><strong>運用の流れ</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"vk_block-margin-lg\\u002d\\u002dmargin-bottom\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vk-color-primary\"}}}},\"textColor\":\"vk-color-primary\"} -->\n<p class=\"has-text-align-center vk_block-margin-lg--margin-bottom has-vk-color-primary-color has-text-color has-link-color\"><strong>Flow</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"vk_block-margin-lg\\u002d\\u002dmargin-bottom\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vk-color-primary\"}}}},\"textColor\":\"vk-color-primary\",\"fontSize\":\"regular\"} -->\n<p class=\"has-text-align-center vk_block-margin-lg--margin-bottom has-vk-color-primary-color has-text-color has-link-color has-regular-font-size\"><strong>ーREHAP導入から報酬支払いー</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:uagb/content-timeline {\"classMigrate\":true,\"childMigrate\":true,\"align\":\"left\",\"headingColor\":\"#151515\",\"subHeadingColor\":\"\",\"separatorFillColor\":\"#942b2b\",\"borderFocus\":\"#942b2b\",\"horizontalSpace\":24,\"verticalSpace\":42,\"timelinAlignment\":\"left\",\"timelinAlignmentTablet\":\"left\",\"timelinAlignmentMobile\":\"left\",\"arrowlinAlignment\":\"top\",\"borderwidth\":1,\"iconBgFocus\":\"#942b2b\",\"dateFontSizeType\":\"px\",\"connectorBgsize\":45,\"block_id\":\"ed6a678b\",\"iconSize\":15,\"displayPostDate\":false,\"leftPadding\":10,\"rightPadding\":0,\"topPadding\":0,\"bottomPadding\":10} -->\n<div class=\"wp-block-uagb-content-timeline uagb-timeline__outer-wrap uagb-block-ed6a678b uagb-timeline__content-wrap uagb-time