(217, 2, '2026-03-02 07:57:07', '2026-03-01 22:57:07', '{\n    \"custom_css[lightning-child-sample]\": {\n        \"value\": \".is-layout-constrained > :where(:not(.alignleft):not(.alignright):not(.alignfull)) {\\n    max-width: 80%;\\n    margin-left: auto !important;\\n    margin-right: auto !important;\\n}\",\n        \"type\": \"custom_css\",\n        \"user_id\": 2,\n        \"date_modified_gmt\": \"2026-03-01 22:57:07\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', 'e70b7f54-5aec-4bb9-a33e-7701cde49fa5', '', '', '2026-03-02 07:57:07', '2026-03-01 22:57:07', '', 0, 'https://relybit.co.jp/rehap/lp/e70b7f54-5aec-4bb9-a33e-7701cde49fa5/', 0, 'customize_changeset', '', 0),
(218, 2, '2026-03-02 07:57:07', '2026-03-01 22:57:07', '.is-layout-constrained > :where(:not(.alignleft):not(.alignright):not(.alignfull)) {\n    max-width: 85%;\n}\n.wp-block-columns.is-layout-flex.wp-container-core-columns-is-layout-e0e4babd.wp-block-columns-is-layout-flex {\n    width: 55%;\n}\n\n.rehap_shikumi{\n  width: 55%;\n  margin: 0 auto;\n	border-radius:10px 10px;\n}\n\nfooter.site-footer{\n  background: #f9f9f9 !important;\n  color: #373737 !important;\n}\n\n\n/* 2行目（Powered by WordPress〜）を非表示 */\n.site-footer .site-footer-copyright p:nth-child(2){\n  display:none;\n}\n\n@media screen and (max-width: 980px) {\n  .is-layout-constrained > :where(:not(.alignleft):not(.alignright):not(.alignfull)) {\n      max-width: 100%;\n  }\n	\n	.wp-block-columns.is-layout-flex.wp-container-core-columns-is-layout-e0e4babd.wp-block-columns-is-layout-flex {\n    width: 100%;\n}\n	.rehap_shikumi{\n  width: 85%;\n}\n}\n\n\n	@media screen and (max-width: 768px) {\n		\n	 :root :where(.is-layout-flex) {\n    gap: 0px;\n  }\n	\n.model_rehap img {\n  max-width: 80%;\n  width: 80%;\n  margin: 30px auto 0;\n  display: block;\n}\n	\n	.rehap_shikumi{\n  width: 90%;\n  margin: 0 auto;\n	padding:10px 5px;\n}\n	.merit {\n    gap: 30px;\n}\n	.tenpo_illust {\n		margin:0 auto;\n		padding-bottom:0px;\n		padding-left:0px;\n		padding-right:0px;\n		gap:5px;\n	}\n	\n	.wp-block-columns.tenpo_illust{\n  padding: 0 0 20px 0 !important;\n}\n\n.contact_botton {\n  width: 100vw !important;\n  max-width: 90vw !important;\n  margin-left: calc(50% - 50vw);\n}\n	\n}\n\n', 'lightning-child-sample', '', 'publish', 'closed', 'closed', '', 'lightning-child-sample', '', '', '2026-03-03 05:30:19', '2026-03-02 20:30:19', '', 0, 'https://relybit.co.jp/rehap/lp/lightning-child-sample/', 0, 'custom_css', '', 0),
