ite\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group vk_block-margin-sm--margin-bottom has-white-background-color has-background\" style=\"border-top-left-radius:12px;border-top-right-radius:12px;border-bottom-left-radius:12px;border-bottom-right-radius:12px;padding-top:0;padding-bottom:0;box-shadow:var(--wp--preset--shadow--natural)\"><!-- wp:vk-blocks/icon {\"faIcon\":\"\\u003ci class=\\u0022fa-solid fa-circle-check\\u0022\\u003e\\u003c/i\\u003e\",\"iconMargin\":12,\"iconType\":\"2\",\"iconColor\":\"vk-color-primary\"} -->\n<div class=\"wp-block-vk-blocks-icon vk_icon\"><div class=\"vk_icon_frame is-style-noline\"><div class=\"vk_icon_border has-text-color has-vk-color-primary-color\" style=\"width:calc(36px + 24px);height:calc(36px + 24px)\"><i class=\"fa-solid vk_icon_font fa-circle-check\"></i></div></div></div>\n<!-- /wp:vk-blocks/icon -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vk-color-primary\"}}}},\"textColor\":\"vk-color-primary\"} -->\n<p class=\"has-vk-color-primary-color has-text-color has-link-color\"><strong><strong>物販には興味があるが、<span data-fontSize=\"18px\" style=\"font-size: 18px;\" class=\"vk_inline-font-size\">在庫リスクは避けたい</span></strong></strong></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"vk_block-margin-sm\\u002d\\u002dmargin-bottom\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"12px\",\"topRight\":\"12px\",\"bottomLeft\":\"12px\",\"bottomRight\":\"12px\"}},\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}},\"shadow\":\"var:preset|shadow|natural\"},\"backgroundColor\":\"white\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group vk_block-margin-sm--margin-bottom has-white-background-color has-background\" style=\"border-top-left-radius:12px;border-top-right-radius:12px;border-bottom-left-radius:12px;border-bottom-right-radius:12px;padding-top:0;padding-bottom:0;box-shadow:var(--wp--preset--shadow--natural)\"><!-- wp:vk-blocks/icon {\"faIcon\":\"\\u003ci class=\\u0022fa-solid fa-circle-check\\u0022\\u003e\\u003c/i\\u003e\",\"iconMargin\":12,\"iconType\":\"2\",\"iconColor\":\"vk-color-primary\"} -->\n<div class=\"wp-block-vk-blocks-icon vk_icon\"><div class=\"vk_icon_frame is-style-noline\"><div class=\"vk_icon_border has-text-color has-vk-color-primary-color\" style=\"width:calc(36px + 24px);height:calc(36px + 24px)\"><i class=\"fa-solid vk_icon_font fa-circle-check\"></i></div></div></div>\n<!-- /wp:vk-blocks/icon -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vk-color-primary\"}}}},\"textColor\":\"vk-color-primary\"} -->\n<p class=\"has-vk-color-primary-color has-text-color has-link-color\"><strong><strong>客単価を上げたいが、<span data-fontSize=\"18px\" style=\"font-size: 18px;\" class=\"vk_inline-font-size\">無理な提案はしたくない</span></strong></strong></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"vk_block-margin-sm\\u002d\\u002dmargin-bottom\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"12px\",\"topRight\":\"12px\",\"bottomLeft\":\"12px\",\"bottomRight\":\"12px\"}},\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}},\"shadow\":\"var:preset|shadow|natural\"},\"backgroundColor\":\"white\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group vk_block-margin-sm--margin-bottom has-white-background-color has-background\" style=\"border-top-left-radius:12px;border-top-right-radius:12px;border-bottom-left-radius:12px;border-bottom-right-radius:12px;padding-top:0;padding-bottom:0;box-shadow:var(--wp--preset--shadow--natural)\"><!-- wp:vk-blocks/icon {\"faIcon\":\"\\u003ci class=\\u0022fa-solid fa-circle-check\\u0022\\u003e\\u003c/i\\u003e\",\"iconMargin\":12,\"iconType\":\"2\",\"iconColor\":\"vk-color-primary\"} -->\n<div class=\"wp-block-vk-blocks-icon vk_icon\"><div class=\"vk_icon_frame is-style-noline\"><div class=\"vk_icon_border has-text-color has-vk-color-primary-color\" style=\"width:calc(36px + 24px);height:calc(36px + 24px)\"><i class=\"fa-solid vk_icon_font fa-circle-check\"></i></div></div></div>\n<!-- /wp:vk-blocks/icon -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vk-color-primary\"}}}},\"textColor\":\"vk-color-primary\"} -->\n<p class=\"has-vk-color-primary-color has-text-color has-link-color\"><strong><strong>スタッフの頑張りを、<span data-fontSize=\"18px\" style=\"font-size: 18px;\" class=\"vk_inline-font-size\">きちんと評価したい</span></strong></strong></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:columns {\"isStackedOnMobile\":false,\"align\":\"full\",\"className\":\"vk_block-margin-0\\u002d\\u002dmargin-bottom\",\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"0px\"}}},\"UAGHideMob\":true,\"UAGResponsiveConditions\":true} -->\n<div class=\"wp-block-columns alignfull is-not-stacked-on-mobile vk_block-margin-0--margin-bottom uag-hide-mob\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":199,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/03/16.webp\" alt=\"\" class=\"wp-image-199\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":201,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/03/17.webp\" alt=\"\" class=\"wp-image-201\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":202,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"vk_block-margin-0\\u002d\\u002dmargin-bottom\"} -->\n<figure class=\"wp-block-image size-full vk_block-margin-0--margin-bottom\"><img src=\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/03/18.webp\" alt=\"\" class=\"wp-image-202\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":203,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"UAGHideMob\":true,\"UAGResponsiveConditions\":true} -->\n<figure class=\"wp-block-image size-full uag-hide-mob\"><img src=\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/03/19.webp\" alt=\"\" class=\"wp-image-203\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:group {\"align\":\"full\",\"layout\":{\"type\":\"constrained\"},\"UAGHideDesktop\":true,\"UAGHideTab\":true,\"UAGResponsiveConditions\":true} -->\n<div class=\"wp-block-group alignfull uag-hide-desktop uag-hide-tab\"><!-- wp:columns {\"isStackedOnMobile\":false,\"align\":\"full\",\"className\":\"vk_block-margin-0\\u002d\\u002dmargin-bottom\",\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"0px\"}}}} -->\n<div class=\"wp-block-columns alignfull is-not-stacked-on-mobile vk_block-margin-0--margin-bottom\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":199,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/03/16.webp\" alt=\"\" class=\"wp-image-199\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":201,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/03/17.webp\" alt=\"\" class=\"wp-image-201\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:columns {\"isStackedOnMobile\":false,\"align\":\"full\",\"className\":\"vk_block-margin-0\\u002d\\u002dmargin-bottom\",\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"0px\"}}}} -->\n<div class=\"wp-block-columns alignfull is-not-stacked-on-mobile vk_block-margin-0--margin-bottom\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":202,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"vk_block-margin-0\\u002d\\u002dmargin-bottom\"} -->\n<figure class=\"wp-block-image size-full vk_block-margin-0--margin-bottom\"><img src=\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/03/18.webp\" alt=\"\" class=\"wp-image-202\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":203,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/03/19.webp\" alt=\"\" class=\"wp-image-203\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#f9f9f9\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-background\" style=\"background-color:#f9f9f9\"><!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"vk_block-margin-xl\\u002d\\u002dmargin-bottom\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}},\"color\":{\"text\":\"#373737\"},\"typography\":{\"fontSize\":\"1.7rem\"}}} -->\n<p class=\"has-text-align-center vk_block-margin-xl--margin-bottom has-text-color has-link-color\" style=\"color:#373737;font-size:1.7rem\"><strong>そんな店舗経営の悩みに</strong><br><strong><span style=\"color: #942b2b;\" class=\"stk-highlight\">信頼を活かす収益モデル “ REHAP</span></strong> <span style=\"color: #942b2b;\" class=\"stk-highlight\">”</span></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:columns {\"verticalAlignment\":null,\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|70\",\"left\":\"var:preset|spacing|70\"}}}} -->\n<div class=\"wp-block-columns\" style=\"padding-right:var(--wp--preset--spacing--70);padding-left:var(--wp--preset--spacing--70)\"><!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}},\"color\":{\"text\":\"#373737\"}},\"fontSize\":\"large\"} -->\n<p class=\"has-text-color has-link-color has-large-font-size\" style=\"color:#373737\"><strong>リアル店舗 × 成果報酬</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"lineHeight\":\"2.1\"},\"color\":{\"text\":\"#373737\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#373737;line-height:2.1\">REHAP（リハップ）は、<br>整体院・サロン・ジム等のさまざまな<br>実店舗ビジネスと信頼できる商品・サービスをつなぐ、<br>成果報酬型パートナーサービスです。</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":114,\"width\":\"358px\",\"height\":\"auto\",\"aspectRatio\":\"0.9116499915211125\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/02/rehap_illust.webp\" alt=\"\" class=\"wp-image-114\" style=\"aspect-ratio:0.9116499915211125;width:358px;height:auto\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"vk_block-margin-xl\\u002d\\u002dmargin-top\",\"style\":{\"color\":{\"text\":\"#373737\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}},\"typography\":{\"lineHeight\":\"1.7\"}}} -->\n<p class=\"has-text-align-center vk_block-margin-xl--margin-top has-text-color has-link-color\" style=\"color:#373737;line-height:1.7\"><strong>REHAPは、単に商品を販売する仕組みではありません。<br>店舗の信頼・価値を守りながら、無理なく収益を生み出すことを目的として設計されています。</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"vk_block-margin-0\\u002d\\u002dmargin-bottom\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vk-color-primary\"}}}},\"textColor\":\"vk-color-primary\",\"fontSize\":\"huge\"} -->\n<p class=\"has-text-align-center vk_block-margin-0--margin-bottom has-vk-color-primary-color has-text-color has-link-color has-huge-font-size\"><strong>サービスの仕組み</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"vk_block-margin-xl\\u002d\\u002dmargin-bottom\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vk-color-primary\"}}}},\"textColor\":\"vk-color-primary\"} -->\n<p class=\"has-text-align-center vk_block-margin-xl--margin-bottom has-vk-color-primary-color has-text-color has-link-color\"><strong>Service structure</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":204,\"width\":\"792px\",\"height\":\"auto\",\"aspectRatio\":\"1.722271100944337\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\",\"className\":\"vk_block-margin-xl\\u002d\\u002dmargin-bottom\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized vk_block-margin-xl--margin-bottom\"><img src=\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/03/rehap_sikumi.webp\" alt=\"\" class=\"wp-image-204\" style=\"aspect-ratio:1.722271100944337;width:792px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"vk_block-margin-md\\u002d\\u002dmargin-bottom vk_block-margin-md\\u002d\\u002dmargin-top\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}},\"color\":{\"text\":\"#373737\"}},\"fontSize\":\"large\"} -->\n<p class=\"has-text-align-center vk_block-margin-md--margin-bottom vk_block-margin-md--margin-top has-text-color has-link-color has-large-font-size\" style=\"color:#373737\"><strong>QRコードを置くだけで収益が生まれる理由</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"vk_block-margin-xl\\u002d\\u002dmargin-bottom\",\"style\":{\"color\":{\"text\":\"#373737\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}},\"typography\":{\"lineHeight\":\"1.7\"}}} -->\n<p class=\"has-text-align-center vk_block-margin-xl--margin-bottom has-text-color has-link-color\" style=\"color:#373737;line-height:1.7\">従来の「成果報酬型広告＝アフィリエイト」はWebメディアやSNSが中心でしたが、<br>REHAPでは、「リアル店舗 × 成果報酬」という新しい形で、<br>店舗の来店客・既存顧客・ファン層を活かした収益化を実現します。<br>REHAPは、単に商品を販売する仕組みではありません。<br>店舗の信頼・価値を守りながら、無理なく収益を生み出すことを目的として設計されています。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#373737\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}}},\"fontSize\":\"large\"} -->\n<p class=\"has-text-align-center has-text-color has-link-color has-large-font-size\" style=\"color:#373737\"><strong>REHAPを導入した店舗では</strong><br><strong>「新しい業務を増やさずに、副収益を得られる環境」が生まれています。</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:vk-blocks/spacer {\"spaceType\":\"height\",\"pc\":120,\"tablet\":50,\"mobile\":40,\"spaceSize\":\"custom\"} -->\n<div class=\"wp-block-vk-blocks-spacer vk_spacer\"><div class=\"vk_spacer-display-pc\" style=\"height:120px\"></div><div class=\"vk_spacer-display-tablet\" style=\"height:50px\"></div><div class=\"vk_spacer-display-mobile\" style=\"height:40px\"></div></div>\n<!-- /wp:vk-blocks/spacer -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#f9f9f9\"},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-background\" style=\"background-color:#f9f9f9;padding-top:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50)\"><!-- wp:vk-blocks/spacer {\"pc\":120,\"tablet\":50,\"mobile\":40,\"spaceSize\":\"custom\"} -->\n<div class=\"wp-block-vk-blocks-spacer vk_spacer\"><div class=\"vk_spacer-display-pc\" style=\"margin-top:120px\"></div><div class=\"vk_spacer-display-tablet\" style=\"margin-top:50px\"></div><div class=\"vk_spacer-display-mobile\" style=\"margin-top:40px\"></div></div>\n<!-- /wp:vk-blocks/spacer -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"vk_block-margin-0\\u002d\\u002dmargin-bottom\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vk-color-primary\"}}}},\"textColor\":\"vk-color-primary\",\"fontSize\":\"huge\"} -->\n<p class=\"has-text-align-center vk_block-margin-0--margin-bottom has-vk-color-primary-color has-text-color has-link-color has-huge-font-size\"><strong>導入メリット</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vk-color-primary\"}}}},\"textColor\":\"vk-color-primary\"} -->\n<p class=\"has-text-align-center has-vk-color-primary-color has-text-color has-link-color\"><strong>Benefits</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:vk-blocks/spacer {\"pc\":50,\"spaceSize\":\"custom\"} -->\n<div class=\"wp-block-vk-blocks-spacer vk_spacer\"><div class=\"vk_spacer-display-pc\" style=\"margin-top:50px\"></div><div class=\"vk_spacer-display-tablet\" style=\"margin-top:30px\"></div><div class=\"vk_spacer-display-mobile\" style=\"margin-top:20px\"></div></div>\n<!-- /wp:vk-blocks/spacer -->\n\n<!-- wp:columns {\"style\":{\"border\":{\"radius\":{\"topLeft\":\"20px\",\"topRight\":\"20px\",\"bottomLeft\":\"20px\",\"bottomRight\":\"20px\"}},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"shadow\":\"var:preset|shadow|natural\"},\"backgroundColor\":\"white\"} -->\n<div class=\"wp-block-columns has-white-background-color has-background\" style=\"border-top-left-radius:20px;border-top-right-radius:20px;border-bottom-left-radius:20px;border-bottom-right-radius:20px;margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--40);box-shadow:var(--wp--preset--shadow--natural)\"><!-- wp:column {\"width\":\"20%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:20%\"><!-- wp:image {\"id\":123,\"width\":\"150px\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/02/2.webp\" alt=\"\" class=\"wp-image-123\" style=\"width:150px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"80%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:80%\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vk-color-primary\"}}}},\"textColor\":\"vk-color-primary\",\"fontSize\":\"large\"} -->\n<p class=\"has-vk-color-primary-color has-text-color has-link-color has-large-font-size\"><strong>01｜初期費用・固定費ゼロで副収益を得られる</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}},\"color\":{\"text\":\"#373737\"}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#373737\">REHAPでは、店舗で商品やサービスを紹介することで、成果に応じた報酬が発生します。成果報酬型のため、初期費用や月額費用、在庫リスクは一切ありません。<br>登録案件の中から、店舗に合った商品・サービスを自由に選べます。</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:vk-blocks/spacer {\"spaceType\":\"height\",\"pc\":50,\"spaceSize\":\"custom\"} -->\n<div class=\"wp-block-vk-blocks-spacer vk_spacer\"><div class=\"vk_spacer-display-pc\" style=\"height:50px\"></div><div class=\"vk_spacer-display-tablet\" style=\"height:30px\"></div><div class=\"vk_spacer-display-mobile\" style=\"height:20px\"></div></div>\n<!-- /wp:vk-blocks/spacer -->\n\n<!-- wp:columns {\"className\":\"is-vk-row-reverse\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"20px\",\"topRight\":\"20px\",\"bottomLeft\":\"20px\",\"bottomRight\":\"20px\"}},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"shadow\":\"var:preset|shadow|natural\"},\"backgroundColor\":\"white\",\"reverse\":true} -->\n<div class=\"wp-block-columns is-vk-row-reverse has-white-background-color has-background\" style=\"border-top-left-radius:20px;border-top-right-radius:20px;border-bottom-left-radius:20px;border-bottom-right-radius:20px;margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--40);box-shadow:var(--wp--preset--shadow--natural)\"><!-- wp:column {\"width\":\"20%\",\"style\":{\"shadow\":\"none\"}} -->\n<div class=\"wp-block-column\" style=\"box-shadow:none;flex-basis:20%\"><!-- wp:image {\"id\":126,\"width\":\"150px\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/02/3.webp\" alt=\"\" class=\"wp-image-126\" style=\"width:150px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"80%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:80%\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vk-color-primary\"}}}},\"textColor\":\"vk-color-primary\",\"fontSize\":\"large\"} -->\n<p class=\"has-vk-color-primary-color has-text-color has-link-color has-large-font-size\"><strong><strong>02｜スタッフ評価・モチベーション向上</strong></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#373737\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#373737\">スタッフごとに販売した件数を可視化していただくことで、スタッフ評価やインセンティブ設計に活用できます。<br>実業務で売上が伸び悩んでいるスタッフも、REHAPでの収益をプラスオンして評価していただけます。</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:vk-blocks/spacer {\"spaceType\":\"height\",\"pc\":50,\"spaceSize\":\"custom\"} -->\n<div class=\"wp-block-vk-blocks-spacer vk_spacer\"><div class=\"vk_spacer-display-pc\" style=\"height:50px\"></div><div class=\"vk_spacer-display-tablet\" style=\"height:30px\"></div><div class=\"vk_spacer-display-mobile\" style=\"height:20px\"></div></div>\n<!-- /wp:vk-blocks/spacer -->\n\n<!-- wp:columns {\"style\":{\"border\":{\"radius\":{\"topLeft\":\"20px\",\"topRight\":\"20px\",\"bottomLeft\":\"20px\",\"bottomRight\":\"20px\"}},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"shadow\":\"var:preset|shadow|natural\"},\"backgroundColor\":\"white\"} -->\n<div class=\"wp-block-columns has-white-background-color has-background\" style=\"border-top-left-radius:20px;border-top-right-radius:20px;border-bottom-left-radius:20px;border-bottom-right-radius:20px;margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--40);box-shadow:var(--wp--preset--shadow--natural)\"><!-- wp:column {\"width\":\"20%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:20%\"><!-- wp:image {\"id\":127,\"width\":\"150px\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/02/4.webp\" alt=\"\" class=\"wp-image-127\" style=\"width:150px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"80%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:80%\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vk-color-primary\"}}}},\"textColor\":\"vk-color-primary\",\"fontSize\":\"large\"} -->\n<p class=\"has-vk-color-primary-color has-text-color has-link-color has-large-font-size\"><strong><strong>03｜自社サービスの売上拡大にも活用できる</strong></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#373737\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#373737\">REHAPでは、店舗様ご自身のサービスを掲載し、Webメディアで紹介することも可能です。<br>比較記事やランキング記事などに掲載され、成果が発生した場合のみ広告費が発生する成果報酬型のため、費用リスクを抑えて集客が行えます。</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:vk-blocks/spacer {\"spaceType\":\"height\",\"spaceSize\":\"large\"} -->\n<div class=\"wp-block-vk-blocks-spacer vk_spacer vk_spacer-type-height\"><div class=\"vk_block-margin-lg--height\"></div></div>\n<!-- /wp:vk-blocks/spacer -->\n\n<!-- wp:columns {\"className\":\"is-vk-row-reverse\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"20px\",\"topRight\":\"20px\",\"bottomLeft\":\"20px\",\"bottomRight\":\"20px\"}},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"shadow\":\"var:preset|shadow|natural\"},\"backgroundColor\":\"white\",\"reverse\":true} -->\n<div class=\"wp-block-columns is-vk-row-reverse has-white-background-color has-background\" style=\"border-top-left-radius:20px;border-top-right-radius:20px;border-bottom-left-radius:20px;border-bottom-right-radius:20px;margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--40);box-shadow:var(--wp--preset--shadow--natural)\"><!-- wp:column {\"width\":\"20%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:20%\"><!-- wp:image {\"id\":128,\"width\":\"150px\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/02/5.webp\" alt=\"\" class=\"wp-image-128\" style=\"width:150px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"80%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:80%\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vk-color-primary\"}}}},\"textColor\":\"vk-color-primary\",\"fontSize\":\"large\"} -->\n<p class=\"has-vk-color-primary-color has-text-color has-link-color has-large-font-size\"><strong><strong><strong>04｜公式サイト・メディアでの無料掲載</strong></strong></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#373737\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#373737\">REHAPの公式サイトに提携店舗様を記載させていただきます。<br>また、導入から3ヶ月以上が経過した店舗様は、弊社が運営するメディアにも紹介記事を掲載させていただきます。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#373737\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}}},\"fontSize\":\"small\"} -->\n<p class=\"has-text-color has-link-color has-small-font-size\" style=\"color:#373737\">※掲載が不要の場合は担当者にご連絡ください。<br>※掲載タイミングはREHAPのシステム状況や対応スケジュールを加味して調整させていただきます。</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:vk-blocks/spacer {\"spaceType\":\"height\",\"pc\":50,\"spaceSize\":\"custom\"} -->\n<div class=\"wp-block-vk-blocks-spacer vk_spacer\"><div class=\"vk_spacer-display-pc\" style=\"height:50px\"></div><div class=\"vk_spacer-display-tablet\" style=\"height:30px\"></div><div class=\"vk_spacer-display-mobile\" style=\"height:20px\"></div></div>\n<!-- /wp:vk-blocks/spacer -->\n\n<!-- wp:columns {\"style\":{\"border\":{\"radius\":{\"topLeft\":\"20px\",\"topRight\":\"20px\",\"bottomLeft\":\"20px\",\"bottomRight\":\"20px\"}},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"shadow\":\"var:preset|shadow|natural\"},\"backgroundColor\":\"white\"} -->\n<div class=\"wp-block-columns has-white-background-color has-background\" style=\"border-top-left-radius:20px;border-top-right-radius:20px;border-bottom-left-radius:20px;border-bottom-right-radius:20px;margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--40);box-shadow:var(--wp--preset--shadow--natural)\"><!-- wp:column {\"width\":\"20%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:20%\"><!-- wp:image {\"id\":129,\"width\":\"150px\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/02/6.webp\" alt=\"\" class=\"wp-image-129\" style=\"width:150px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"80%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:80%\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vk-color-primary\"}}}},\"textColor\":\"vk-color-primary\",\"fontSize\":\"large\"} -->\n<p class=\"has-vk-color-primary-color has-text-color has-link-color has-large-font-size\"><strong><strong><strong>05｜交流会での無料PR掲出権</strong></strong></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#373737\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#373737\">運営会社リリビットが主催する交流会やイベントにおいて、店舗様のチラシやパンフレットを掲出していただくことが可能です。<br>直接他事業者にアプローチできるため、販路拡大や認知向上が期待できます。</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:vk-blocks/spacer {\"spaceType\":\"height\",\"pc\":50,\"spaceSize\":\"custom\"} -->\n<div class=\"wp-block-vk-blocks-spacer vk_spacer\"><div class=\"vk_spacer-display-pc\" style=\"height:50px\"></div><div class=\"vk_spacer-display-tablet\" style=\"height:30px\"></div><div class=\"vk_spacer-display-mobile\" style=\"height:20px\"></div></div>\n<!-- /wp:vk-blocks/spacer -->\n\n<!-- wp:columns {\"className\":\"is-vk-row-reverse\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"20px\",\"topRight\":\"20px\",\"bottomLeft\":\"20px\",\"bottomRight\":\"20px\"}},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"shadow\":\"var:preset|shadow|natural\"},\"backgroundColor\":\"white\",\"reverse\":true} -->\n<div class=\"wp-block-columns is-vk-row-reverse has-white-background-color has-background\" style=\"border-top-left-radius:20px;border-top-right-radius:20px;border-bottom-left-radius:20px;border-bottom-right-radius:20px;margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--40);box-shadow:var(--wp--preset--shadow--natural)\"><!-- wp:column {\"width\":\"20%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:20%\"><!-- wp:image {\"id\":130,\"width\":\"150px\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"https://relybit.co.jp/rehap/lp/wp-content/uploads/2026/02/7.webp\" alt=\"\" class=\"wp-image-130\" style=\"width:150px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"80%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:80%\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vk-color-primary\"}}}},\"textColor\":\"vk-color-primary\",\"fontSize\":\"large\"} -->\n<p class=\"has-vk-color-primary-color has-text-color has-link-color has-large-font-size\"><strong><strong><strong><strong>06｜Webマーケティングの無料相談</strong></strong></strong></strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}},\"color\":{\"text\":\"#373737\"}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#373737\">REHAPをご導入いただいた店舗様は、弊社にてWebマーケティング全般についての無料相談をご利用いただくことが可能です。<br>売上拡大・集客・採用・認知向上といったさまざまなお悩みをご相談いただけます。</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:vk-blocks/spacer {\"spaceType\":\"height\",\"pc\":50,\"spaceSize\":\"custom\"} -->\n<div class=\"wp-block-vk-blocks-spacer vk_spacer\"><div class=\"vk_spacer-display-pc\" style=\"height:50px\"></div><div class=\"vk_spacer-display-tablet\" style=\"height:30px\"></div><div class=\"vk_spacer-display-mobile\" style=\"height:20px\"></div></div>\n<!-- /wp:vk-blocks/spacer -->\n\n<!-- wp:columns {\"className\":\"is-vk-row-reverse\",