(253, 2, '2026-03-02 09:11:54', '2026-03-02 00:11:54', '{\n    \"custom_css[lightning-child-sample]\": {\n        \"value\": \".is-layout-constrained > :where(:not(.alignleft):not(.alignright):not(.alignfull)) {\\n    max-width: 85%;\\n}\\n\\n\\n@media screen and (max-width: 768px) {\\n  .is-layout-constrained > :where(:not(.alignleft):not(.alignright):not(.alignfull)) {\\n      max-width: 100%;\\n  }\\n}\\n\\n\",\n        \"type\": \"custom_css\",\n        \"user_id\": 2,\n        \"date_modified_gmt\": \"2026-03-02 00:11:54\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', '84b7918d-e2fd-44fd-87e5-90be95a3941d', '', '', '2026-03-02 09:11:54', '2026-03-02 00:11:54', '', 0, 'https://relybit.co.jp/rehap/lp/84b7918d-e2fd-44fd-87e5-90be95a3941d/', 0, 'customize_changeset', '', 0),
