{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-background\" style=\"background-color:#f9f9f9\"><!-- wp:vk-blocks/spacer {\"spaceType\":\"height\",\"pc\":120,\"tablet\":50,\"mobile\":40,\"spaceSize\":\"custom\"} -->\n<div class=\"wp-block-vk-blocks-spacer vk_spacer\"><div class=\"vk_spacer-display-pc\" style=\"height:120px\"></div><div class=\"vk_spacer-display-tablet\" style=\"height:50px\"></div><div class=\"vk_spacer-display-mobile\" style=\"height:40px\"></div></div>\n<!-- /wp:vk-blocks/spacer -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"vk_block-margin-0\\u002d\\u002dmargin-bottom\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vk-color-primary\"}}}},\"textColor\":\"vk-color-primary\",\"fontSize\":\"huge\"} -->\n<p class=\"has-text-align-center vk_block-margin-0--margin-bottom has-vk-color-primary-color has-text-color has-link-color has-huge-font-size\"><strong>よくある質問</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"vk_block-margin-lg\\u002d\\u002dmargin-bottom\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vk-color-primary\"}}}},\"textColor\":\"vk-color-primary\"} -->\n<p class=\"has-text-align-center vk_block-margin-lg--margin-bottom has-vk-color-primary-color has-text-color has-link-color\"><strong>FAQ</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"vk-has-white-color is-style-default\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0px\",\"left\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":{\"topLeft\":\"20px\",\"topRight\":\"20px\",\"bottomLeft\":\"20px\",\"bottomRight\":\"20px\"}},\"shadow\":\"var:preset|shadow|natural\"},\"backgroundColor\":\"white\",\"layout\":{\"type\":\"constrained\"},\"color\":\"#ffffff\"} -->\n<div class=\"wp-block-group vk-has-white-color is-style-default has-white-background-color has-background\" style=\"border-top-left-radius:20px;border-top-right-radius:20px;border-bottom-left-radius:20px;border-bottom-right-radius:20px;padding-top:0;padding-right:var(--wp--preset--spacing--30);padding-bottom:0px;padding-left:var(--wp--preset--spacing--30);box-shadow:var(--wp--preset--shadow--natural)\"><!-- wp:vk-blocks/faq2 {\"className\":\"is-style-vk_faq-normal vk_block-margin-sm\\u002d\\u002dmargin-bottom\"} -->\n<div class=\"wp-block-vk-blocks-faq2 vk_faq  [accordion_trigger_switch] is-style-vk_faq-normal vk_block-margin-sm--margin-bottom\"><div class=\"vk_faq-header\"></div><dl class=\"vk_faq-body\"><!-- wp:vk-blocks/faq2-q -->\n<dt class=\"wp-block-vk-blocks-faq2-q vk_faq_title\" aria-label=\"質問\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}},\"color\":{\"text\":\"#373737\"}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#373737\">本当に費用は一切かかりませんか？</p>\n<!-- /wp:paragraph --></dt>\n<!-- /wp:vk-blocks/faq2-q -->\n\n<!-- wp:vk-blocks/faq2-a -->\n<dd class=\"wp-block-vk-blocks-faq2-a vk_faq_content\" aria-label=\"回答\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}},\"color\":{\"text\":\"#373737\"}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#373737\"><span style=\"color: #373737;\" class=\"stk-highlight\"><strong>はい。初期費用・月額費用・固定費は一切かかりません。<br></strong>成果が発生した場合のみ、広告主から成果報酬が支払われる仕組みのため、店舗様に費用が発生することはありません。</span></p>\n<!-- /wp:paragraph --></dd>\n<!-- /wp:vk-blocks/faq2-a --></dl><div class=\"vk_faq-footer\"></div></div>\n<!-- /wp:vk-blocks/faq2 --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"vk-has-white-color is-style-default\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0px\",\"left\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":{\"topLeft\":\"20px\",\"topRight\":\"20px\",\"bottomLeft\":\"20px\",\"bottomRight\":\"20px\"}},\"shadow\":\"var:preset|shadow|natural\"},\"backgroundColor\":\"white\",\"layout\":{\"type\":\"constrained\"},\"color\":\"#ffffff\"} -->\n<div class=\"wp-block-group vk-has-white-color is-style-default has-white-background-color has-background\" style=\"border-top-left-radius:20px;border-top-right-radius:20px;border-bottom-left-radius:20px;border-bottom-right-radius:20px;padding-top:0;padding-right:var(--wp--preset--spacing--30);padding-bottom:0px;padding-left:var(--wp--preset--spacing--30);box-shadow:var(--wp--preset--shadow--natural)\"><!-- wp:vk-blocks/faq2 {\"className\":\"is-style-vk_faq-normal vk_block-margin-sm\\u002d\\u002dmargin-bottom\"} -->\n<div class=\"wp-block-vk-blocks-faq2 vk_faq  [accordion_trigger_switch] is-style-vk_faq-normal vk_block-margin-sm--margin-bottom\"><div class=\"vk_faq-header\"></div><dl class=\"vk_faq-body\"><!-- wp:vk-blocks/faq2-q -->\n<dt class=\"wp-block-vk-blocks-faq2-q vk_faq_title\" aria-label=\"質問\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}},\"color\":{\"text\":\"#373737\"}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#373737\"><span style=\"color: #373737;\" class=\"stk-highlight\">在庫を持ったり、仕入れを行ったりする必要はありますか？</span></p>\n<!-- /wp:paragraph --></dt>\n<!-- /wp:vk-blocks/faq2-q -->\n\n<!-- wp:vk-blocks/faq2-a -->\n<dd class=\"wp-block-vk-blocks-faq2-a vk_faq_content\" aria-label=\"回答\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}},\"color\":{\"text\":\"#373737\"}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#373737\"><span style=\"color: #373737;\" class=\"stk-highlight\"><strong>いいえ、在庫や仕入れは一切不要です。<br></strong>REHAPは成果報酬型のため、商品を紹介するだけで、在庫リスクは発生しません。</span></p>\n<!-- /wp:paragraph --></dd>\n<!-- /wp:vk-blocks/faq2-a --></dl><div class=\"vk_faq-footer\"></div></div>\n<!-- /wp:vk-blocks/faq2 --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"vk-has-white-color is-style-default\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0px\",\"left\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":{\"topLeft\":\"20px\",\"topRight\":\"20px\",\"bottomLeft\":\"20px\",\"bottomRight\":\"20px\"}},\"shadow\":\"var:preset|shadow|natural\"},\"backgroundColor\":\"white\",\"layout\":{\"type\":\"constrained\"},\"color\":\"#ffffff\"} -->\n<div class=\"wp-block-group vk-has-white-color is-style-default has-white-background-color has-background\" style=\"border-top-left-radius:20px;border-top-right-radius:20px;border-bottom-left-radius:20px;border-bottom-right-radius:20px;padding-top:0;padding-right:var(--wp--preset--spacing--30);padding-bottom:0px;padding-left:var(--wp--preset--spacing--30);box-shadow:var(--wp--preset--shadow--natural)\"><!-- wp:vk-blocks/faq2 {\"className\":\"is-style-vk_faq-normal vk_block-margin-sm\\u002d\\u002dmargin-bottom\"} -->\n<div class=\"wp-block-vk-blocks-faq2 vk_faq  [accordion_trigger_switch] is-style-vk_faq-normal vk_block-margin-sm--margin-bottom\"><div class=\"vk_faq-header\"></div><dl class=\"vk_faq-body\"><!-- wp:vk-blocks/faq2-q -->\n<dt class=\"wp-block-vk-blocks-faq2-q vk_faq_title\" aria-label=\"質問\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}},\"color\":{\"text\":\"#373737\"}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#373737\"><span style=\"color: #373737;\" class=\"stk-highlight\">スタッフに営業や販売をさせる必要はありますか？</span></p>\n<!-- /wp:paragraph --></dt>\n<!-- /wp:vk-blocks/faq2-q -->\n\n<!-- wp:vk-blocks/faq2-a -->\n<dd class=\"wp-block-vk-blocks-faq2-a vk_faq_content\" aria-label=\"回答\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}},\"color\":{\"text\":\"#373737\"}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#373737\"><span style=\"color: #373737;\" class=\"stk-highlight\"><strong>無理な営業や売り込みは一切必要ありません。<br></strong>興味を持たれたお客様に対して、QRコードをご案内いただくだけで問題ありません。</span></p>\n<!-- /wp:paragraph --></dd>\n<!-- /wp:vk-blocks/faq2-a --></dl><div class=\"vk_faq-footer\"></div></div>\n<!-- /wp:vk-blocks/faq2 --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"vk-has-white-color is-style-default\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0px\",\"left\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":{\"topLeft\":\"20px\",\"topRight\":\"20px\",\"bottomLeft\":\"20px\",\"bottomRight\":\"20px\"}},\"shadow\":\"var:preset|shadow|natural\"},\"backgroundColor\":\"white\",\"layout\":{\"type\":\"constrained\"},\"color\":\"#ffffff\"} -->\n<div class=\"wp-block-group vk-has-white-color is-style-default has-white-background-color has-background\" style=\"border-top-left-radius:20px;border-top-right-radius:20px;border-bottom-left-radius:20px;border-bottom-right-radius:20px;padding-top:0;padding-right:var(--wp--preset--spacing--30);padding-bottom:0px;padding-left:var(--wp--preset--spacing--30);box-shadow:var(--wp--preset--shadow--natural)\"><!-- wp:vk-blocks/faq2 {\"className\":\"is-style-vk_faq-normal vk_block-margin-sm\\u002d\\u002dmargin-bottom\"} -->\n<div class=\"wp-block-vk-blocks-faq2 vk_faq  [accordion_trigger_switch] is-style-vk_faq-normal vk_block-margin-sm--margin-bottom\"><div class=\"vk_faq-header\"></div><dl class=\"vk_faq-body\"><!-- wp:vk-blocks/faq2-q -->\n<dt class=\"wp-block-vk-blocks-faq2-q vk_faq_title\" aria-label=\"質問\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}},\"color\":{\"text\":\"#373737\"}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#373737\"><span style=\"color: #373737;\" class=\"stk-highlight\">どのような店舗が利用できますか？</span></p>\n<!-- /wp:paragraph --></dt>\n<!-- /wp:vk-blocks/faq2-q -->\n\n<!-- wp:vk-blocks/faq2-a -->\n<dd class=\"wp-block-vk-blocks-faq2-a vk_faq_content\" aria-label=\"回答\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}},\"color\":{\"text\":\"#373737\"}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#373737\"><span style=\"color: #373737;\" class=\"stk-highlight\"><strong>整体院・サロン・ジムなど、来店型の実店舗ビジネスが対象です。<br></strong>さまざまな店舗が対象となりますので、詳しくは担当者までお問い合わせください。</span></p>\n<!-- /wp:paragraph --></dd>\n<!-- /wp:vk-blocks/faq2-a --></dl><div class=\"vk_faq-footer\"></div></div>\n<!-- /wp:vk-blocks/faq2 --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"vk-has-white-color is-style-default\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0px\",\"left\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":{\"topLeft\":\"20px\",\"topRight\":\"20px\",\"bottomLeft\":\"20px\",\"bottomRight\":\"20px\"}},\"shadow\":\"var:preset|shadow|natural\"},\"backgroundColor\":\"white\",\"layout\":{\"type\":\"constrained\"},\"color\":\"#ffffff\"} -->\n<div class=\"wp-block-group vk-has-white-color is-style-default has-white-background-color has-background\" style=\"border-top-left-radius:20px;border-top-right-radius:20px;border-bottom-left-radius:20px;border-bottom-right-radius:20px;padding-top:0;padding-right:var(--wp--preset--spacing--30);padding-bottom:0px;padding-left:var(--wp--preset--spacing--30);box-shadow:var(--wp--preset--shadow--natural)\"><!-- wp:vk-blocks/faq2 {\"className\":\"is-style-vk_faq-normal vk_block-margin-sm\\u002d\\u002dmargin-bottom\"} -->\n<div class=\"wp-block-vk-blocks-faq2 vk_faq  [accordion_trigger_switch] is-style-vk_faq-normal vk_block-margin-sm--margin-bottom\"><div class=\"vk_faq-header\"></div><dl class=\"vk_faq-body\"><!-- wp:vk-blocks/faq2-q -->\n<dt class=\"wp-block-vk-blocks-faq2-q vk_faq_title\" aria-label=\"質問\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}},\"color\":{\"text\":\"#373737\"}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#373737\"><span style=\"color: #373737;\" class=\"stk-highlight\">紹介できる商品・サービスは自由に選べますか？</span></p>\n<!-- /wp:paragraph --></dt>\n<!-- /wp:vk-blocks/faq2-q -->\n\n<!-- wp:vk-blocks/faq2-a -->\n<dd class=\"wp-block-vk-blocks-faq2-a vk_faq_content\" aria-label=\"回答\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}},\"color\":{\"text\":\"#373737\"}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#373737\"><span style=\"color: #373737;\" class=\"stk-highlight\"><strong>はい。REHAPに登録されている案件の中から自由に選択可能です。<br></strong>店舗の方針や顧客層に合った案件のみをお選びいただけます</span></p>\n<!-- /wp:paragraph --></dd>\n<!-- /wp:vk-blocks/faq2-a --></dl><div class=\"vk_faq-footer\"></div></div>\n<!-- /wp:vk-blocks/faq2 --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"vk-has-white-color is-style-default\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0px\",\"left\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":{\"topLeft\":\"20px\",\"topRight\":\"20px\",\"bottomLeft\":\"20px\",\"bottomRight\":\"20px\"}},\"shadow\":\"var:preset|shadow|natural\"},\"backgroundColor\":\"white\",\"layout\":{\"type\":\"constrained\"},\"color\":\"#ffffff\"} -->\n<div class=\"wp-block-group vk-has-white-color is-style-default has-white-background-color has-background\" style=\"border-top-left-radius:20px;border-top-right-radius:20px;border-bottom-left-radius:20px;border-bottom-right-radius:20px;padding-top:0;padding-right:var(--wp--preset--spacing--30);padding-bottom:0px;padding-left:var(--wp--preset--spacing--30);box-shadow:var(--wp--preset--shadow--natural)\"><!-- wp:vk-blocks/faq2 {\"className\":\"is-style-vk_faq-normal vk_block-margin-sm\\u002d\\u002dmargin-bottom\"} -->\n<div class=\"wp-block-vk-blocks-faq2 vk_faq  [accordion_trigger_switch] is-style-vk_faq-normal vk_block-margin-sm--margin-bottom\"><div class=\"vk_faq-header\"></div><dl class=\"vk_faq-body\"><!-- wp:vk-blocks/faq2-q -->\n<dt class=\"wp-block-vk-blocks-faq2-q vk_faq_title\" aria-label=\"質問\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}},\"color\":{\"text\":\"#373737\"}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#373737\"><span style=\"color: #373737;\" class=\"stk-highlight\">複数の商品・サービスを同時に扱うことはできますか？</span></p>\n<!-- /wp:paragraph --></dt>\n<!-- /wp:vk-blocks/faq2-q -->\n\n<!-- wp:vk-blocks/faq2-a -->\n<dd class=\"wp-block-vk-blocks-faq2-a vk_faq_content\" aria-label=\"回答\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}},\"color\":{\"text\":\"#373737\"}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#373737\"><span style=\"color: #373737;\" class=\"stk-highlight\"><strong>はい。複数案件を同時に扱うことが可能です。<br></strong>案件ごとにQRコードを発行し、用途に応じて設置・切り替えができます。</span></p>\n<!-- /wp:paragraph --></dd>\n<!-- /wp:vk-blocks/faq2-a --></dl><div class=\"vk_faq-footer\"></div></div>\n<!-- /wp:vk-blocks/faq2 --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"vk-has-white-color is-style-default\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0px\",\"left\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":{\"topLeft\":\"20px\",\"topRight\":\"20px\",\"bottomLeft\":\"20px\",\"bottomRight\":\"20px\"}},\"shadow\":\"var:preset|shadow|natural\"},\"backgroundColor\":\"white\",\"layout\":{\"type\":\"constrained\"},\"color\":\"#ffffff\"} -->\n<div class=\"wp-block-group vk-has-white-color is-style-default has-white-background-color has-background\" style=\"border-top-left-radius:20px;border-top-right-radius:20px;border-bottom-left-radius:20px;border-bottom-right-radius:20px;padding-top:0;padding-right:var(--wp--preset--spacing--30);padding-bottom:0px;padding-left:var(--wp--preset--spacing--30);box-shadow:var(--wp--preset--shadow--natural)\"><!-- wp:vk-blocks/faq2 {\"className\":\"is-style-vk_faq-normal vk_block-margin-sm\\u002d\\u002dmargin-bottom\"} -->\n<div class=\"wp-block-vk-blocks-faq2 vk_faq  [accordion_trigger_switch] is-style-vk_faq-normal vk_block-margin-sm--margin-bottom\"><div class=\"vk_faq-header\"></div><dl class=\"vk_faq-body\"><!-- wp:vk-blocks/faq2-q -->\n<dt class=\"wp-block-vk-blocks-faq2-q vk_faq_title\" aria-label=\"質問\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}},\"color\":{\"text\":\"#373737\"}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#373737\"><span style=\"color: #373737;\" class=\"stk-highlight\">QRコードの設置場所に制限はありますか？</span></p>\n<!-- /wp:paragraph --></dt>\n<!-- /wp:vk-blocks/faq2-q -->\n\n<!-- wp:vk-blocks/faq2-a -->\n<dd class=\"wp-block-vk-blocks-faq2-a vk_faq_content\" aria-label=\"回答\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}},\"color\":{\"text\":\"#373737\"}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#373737\"><span style=\"color: #373737;\" class=\"stk-highlight\"><strong>特に制限はありません。<br></strong>受付・カウンター・店内POP・施術後の案内など、店舗様の運営に合わせて自由に設置いただけます。</span></p>\n<!-- /wp:paragraph --></dd>\n<!-- /wp:vk-blocks/faq2-a --></dl><div class=\"vk_faq-footer\"></div></div>\n<!-- /wp:vk-blocks/faq2 --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"vk-has-white-color is-style-default\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0px\",\"left\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":{\"topLeft\":\"20px\",\"topRight\":\"20px\",\"bottomLeft\":\"20px\",\"bottomRight\":\"20px\"}},\"shadow\":\"var:preset|shadow|natural\"},\"backgroundColor\":\"white\",\"layout\":{\"type\":\"constrained\"},\"color\":\"#ffffff\"} -->\n<div class=\"wp-block-group vk-has-white-color is-style-default has-white-background-color has-background\" style=\"border-top-left-radius:20px;border-top-right-radius:20px;border-bottom-left-radius:20px;border-bottom-right-radius:20px;padding-top:0;padding-right:var(--wp--preset--spacing--30);padding-bottom:0px;padding-left:var(--wp--preset--spacing--30);box-shadow:var(--wp--preset--shadow--natural)\"><!-- wp:vk-blocks/faq2 {\"className\":\"is-style-vk_faq-normal vk_block-margin-sm\\u002d\\u002dmargin-bottom\"} -->\n<div class=\"wp-block-vk-blocks-faq2 vk_faq  [accordion_trigger_switch] is-style-vk_faq-normal vk_block-margin-sm--margin-bottom\"><div class=\"vk_faq-header\"></div><dl class=\"vk_faq-body\"><!-- wp:vk-blocks/faq2-q -->\n<dt class=\"wp-block-vk-blocks-faq2-q vk_faq_title\" aria-label=\"質問\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}},\"color\":{\"text\":\"#373737\"}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#373737\"><span style=\"color: #373737;\" class=\"stk-highlight\">SNSやホームページからの申込みも成果対象になりますか？</span></p>\n<!-- /wp:paragraph --></dt>\n<!-- /wp:vk-blocks/faq2-q -->\n\n<!-- wp:vk-blocks/faq2-a -->\n<dd class=\"wp-block-vk-blocks-faq2-a vk_faq_content\" aria-label=\"回答\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}},\"color\":{\"text\":\"#373737\"}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#373737\"><strong>はい。店舗専用URL・QRコード経由であれば成果対象となります。<br></strong>店舗の公式サイトやSNSでのご案内にもご利用いただけます。</p>\n<!-- /wp:paragraph --></dd>\n<!-- /wp:vk-blocks/faq2-a --></dl><div class=\"vk_faq-footer\"></div></div>\n<!-- /wp:vk-blocks/faq2 --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"vk-has-white-color is-style-default\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0px\",\"left\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":{\"topLeft\":\"20px\",\"topRight\":\"20px\",\"bottomLeft\":\"20px\",\"bottomRight\":\"20px\"}},\"shadow\":\"var:preset|shadow|natural\"},\"backgroundColor\":\"white\",\"layout\":{\"type\":\"constrained\"},\"color\":\"#ffffff\"} -->\n<div class=\"wp-block-group vk-has-white-color is-style-default has-white-background-color has-background\" style=\"border-top-left-radius:20px;border-top-right-radius:20px;border-bottom-left-radius:20px;border-bottom-right-radius:20px;padding-top:0;padding-right:var(--wp--preset--spacing--30);padding-bottom:0px;padding-left:var(--wp--preset--spacing--30);box-shadow:var(--wp--preset--shadow--natural)\"><!-- wp:vk-blocks/faq2 {\"className\":\"is-style-vk_faq-normal vk_block-margin-sm\\u002d\\u002dmargin-bottom\"} -->\n<div class=\"wp-block-vk-blocks-faq2 vk_faq  [accordion_trigger_switch] is-style-vk_faq-normal vk_block-margin-sm--margin-bottom\"><div class=\"vk_faq-header\"></div><dl class=\"vk_faq-body\"><!-- wp:vk-blocks/faq2-q -->\n<dt class=\"wp-block-vk-blocks-faq2-q vk_faq_title\" aria-label=\"質問\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}},\"color\":{\"text\":\"#373737\"}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#373737\"><span style=\"color: #373737;\" class=\"stk-highlight\">法律面（薬機法・景表法）は問題ありませんか？</span></p>\n<!-- /wp:paragraph --></dt>\n<!-- /wp:vk-blocks/faq2-q -->\n\n<!-- wp:vk-blocks/faq2-a -->\n<dd class=\"wp-block-vk-blocks-faq2-a vk_faq_content\" aria-label=\"回答\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}},\"color\":{\"text\":\"#373737\"}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#373737\"><span style=\"color: #373737;\" class=\"stk-highlight\"><strong>REHAPでは薬機法・景表法に配慮した案件のみを取り扱っています。<br></strong>また、店舗様が過度な表現を行わなくて済む運用設計を行っています。登録されている広告主はREHAP登録時に審査を経ております。また、運営会社に有資格者もおりますので、安心してご利用いただけます。</span></p>\n<!-- /wp:paragraph --></dd>\n<!-- /wp:vk-blocks/faq2-a --></dl><div class=\"vk_faq-footer\"></div></div>\n<!-- /wp:vk-blocks/faq2 --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"vk-has-white-color is-style-default\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0px\",\"left\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":{\"topLeft\":\"20px\",\"topRight\":\"20px\",\"bottomLeft\":\"20px\",\"bottomRight\":\"20px\"}},\"shadow\":\"var:preset|shadow|natural\"},\"backgroundColor\":\"white\",\"layout\":{\"type\":\"constrained\"},\"color\":\"#ffffff\"} -->\n<div class=\"wp-block-group vk-has-white-color is-style-default has-white-background-color has-background\" style=\"border-top-left-radius:20px;border-top-right-radius:20px;border-bottom-left-radius:20px;border-bottom-right-radius:20px;padding-top:0;padding-right:var(--wp--preset--spacing--30);padding-bottom:0px;padding-left:var(--wp--preset--spacing--30);box-shadow:var(--wp--preset--shadow--natural)\"><!-- wp:vk-blocks/faq2 {\"className\":\"is-style-vk_faq-normal vk_block-margin-sm\\u002d\\u002dmargin-bottom\"} -->\n<div class=\"wp-block-vk-blocks-faq2 vk_faq  [accordion_trigger_switch] is-style-vk_faq-normal vk_block-margin-sm--margin-bottom\"><div class=\"vk_faq-header\"></div><dl class=\"vk_faq-body\"><!-- wp:vk-blocks/faq2-q -->\n<dt class=\"wp-block-vk-blocks-faq2-q vk_faq_title\" aria-label=\"質問\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}},\"color\":{\"text\":\"#373737\"}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#373737\"><span style=\"color: #373737;\" class=\"stk-highlight\">導入までにどれくらい時間がかかりますか？</span></p>\n<!-- /wp:paragraph --></dt>\n<!-- /wp:vk-blocks/faq2-q -->\n\n<!-- wp:vk-blocks/faq2-a -->\n<dd class=\"wp-block-vk-blocks-faq2-a vk_faq_content\" aria-label=\"回答\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}},\"color\":{\"text\":\"#373737\"}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#373737\"><span style=\"color: #373737;\" class=\"stk-highlight\"><strong>店舗登録後、即日～5営業日ほどで利用開始が可能です。<br></strong>登録完了後、案件をご選択いただき、弊社からQRコードを送付させていただきます。</span></p>\n<!-- /wp:paragraph --></dd>\n<!-- /wp:vk-blocks/faq2-a --></dl><div class=\"vk_faq-footer\"></div></div>\n<!-- /wp:vk-blocks/faq2 --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"vk-has-white-color is-style-default\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0px\",\"left\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":{\"topLeft\":\"20px\",\"topRight\":\"20px\",\"bottomLeft\":\"20px\",\"bottomRight\":\"20px\"}},\"shadow\":\"var:preset|shadow|natural\"},\"backgroundColor\":\"white\",\"layout\":{\"type\":\"constrained\"},\"color\":\"#ffffff\"} -->\n<div class=\"wp-block-group vk-has-white-color is-style-default has-white-background-color has-background\" style=\"border-top-left-radius:20px;border-top-right-radius:20px;border-bottom-left-radius:20px;border-bottom-right-radius:20px;padding-top:0;padding-right:var(--wp--preset--spacing--30);padding-bottom:0px;padding-left:var(--wp--preset--spacing--30);box-shadow:var(--wp--preset--shadow--natural)\"><!-- wp:vk-blocks/faq2 {\"className\":\"is-style-vk_faq-normal vk_block-margin-sm\\u002d\\u002dmargin-bottom\"} -->\n<div class=\"wp-block-vk-blocks-faq2 vk_faq  [accordion_trigger_switch] is-style-vk_faq-normal vk_block-margin-sm--margin-bottom\"><div class=\"vk_faq-header\"></div><dl class=\"vk_faq-body\"><!-- wp:vk-blocks/faq2-q -->\n<dt class=\"wp-block-vk-blocks-faq2-q vk_faq_title\" aria-label=\"質問\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}},\"color\":{\"text\":\"#373737\"}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#373737\"><span style=\"color: #373737;\" class=\"stk-highlight\">途中で利用をやめることはできますか？</span></p>\n<!-- /wp:paragraph --></dt>\n<!-- /wp:vk-blocks/faq2-q -->\n\n<!-- wp:vk-blocks/faq2-a -->\n<dd class=\"wp-block-vk-blocks-faq2-a vk_faq_content\" aria-label=\"回答\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}},\"color\":{\"text\":\"#373737\"}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#373737\"><span style=\"color: #373737;\" class=\"stk-highlight\"><strong>はい。いつでも利用停止が可能です。<br></strong>契約期間の縛りや違約金などは一切ありません。専用のフォームからご連絡いただくだけで利用停止となります。</span></p>\n<!-- /wp:paragraph --></dd>\n<!-- /wp:vk-blocks/faq2-a --></dl><div class=\"vk_faq-footer\"></div></div>\n<!-- /wp:vk-blocks/faq2 --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"vk-has-white-color is-style-default\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0px\",\"left\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":{\"topLeft\":\"20px\",\"topRight\":\"20px\",\"bottomLeft\":\"20px\",\"bottomRight\":\"20px\"}},\"shadow\":\"var:preset|shadow|natural\"},\"backgroundColor\":\"white\",\"layout\":{\"type\":\"constrained\"},\"color\":\"#ffffff\"} -->\n<div class=\"wp-block-group vk-has-white-color is-style-default has-white-background-color has-background\" style=\"border-top-left-radius:20px;border-top-right-radius:20px;border-bottom-left-radius:20px;border-bottom-right-radius:20px;padding-top:0;padding-right:var(--wp--preset--spacing--30);padding-bottom:0px;padding-left:var(--wp--preset--spacing--30);box-shadow:var(--wp--preset--shadow--natural)\"><!-- wp:vk-blocks/faq2 {\"className\":\"is-style-vk_faq-normal vk_block-margin-sm\\u002d\\u002dmargin-bottom\"} -->\n<div class=\"wp-block-vk-blocks-faq2 vk_faq  [accordion_trigger_switch] is-style-vk_faq-normal vk_block-margin-sm--margin-bottom\"><div class=\"vk_faq-header\"></div><dl class=\"vk_faq-body\"><!-- wp:vk-blocks/faq2-q -->\n<dt class=\"wp-block-vk-blocks-faq2-q vk_faq_title\" aria-label=\"質問\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}},\"color\":{\"text\":\"#373737\"}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#373737\"><span style=\"color: #373737;\" class=\"stk-highlight\">売上が発生しなかった場合でも問題ありませんか？</span></p>\n<!-- /wp:paragraph --></dt>\n<!-- /wp:vk-blocks/faq2-q -->\n\n<!-- wp:vk-blocks/faq2-a -->\n<dd class=\"wp-block-vk-blocks-faq2-a vk_faq_content\" aria-label=\"回答\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}},\"color\":{\"text\":\"#373737\"}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#373737\"><span style=\"color: #373737;\" class=\"stk-highlight\"><strong>はい。売上が発生しなかった場合でもペナルティはありません。<br></strong>費用負担も発生しないため、リスクなくお試しいただけます。</span></p>\n<!-- /wp:paragraph --></dd>\n<!-- /wp:vk-blocks/faq2-a --></dl><div class=\"vk_faq-footer\"></div></div>\n<!-- /wp:vk-blocks/faq2 --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"vk-has-white-color is-style-default\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0px\",\"left\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":{\"topLeft\":\"20px\",\"topRight\":\"20px\",\"bottomLeft\":\"20px\",\"bottomRight\":\"20px\"}},\"shadow\":\"var:preset|shadow|natural\"},\"backgroundColor\":\"white\",\"layout\":{\"type\":\"constrained\"},\"color\":\"#ffffff\"} -->\n<div class=\"wp-block-group vk-has-white-color is-style-default has-white-background-color has-background\" style=\"border-top-left-radius:20px;border-top-right-radius:20px;border-bottom-left-radius:20px;border-bottom-right-radius:20px;padding-top:0;padding-right:var(--wp--preset--spacing--30);padding-bottom:0px;padding-left:var(--wp--preset--spacing--30);box-shadow:var(--wp--preset--shadow--natural)\"><!-- wp:vk-blocks/faq2 {\"className\":\"is-style-vk_faq-normal vk_block-margin-sm\\u002d\\u002dmargin-bottom\"} -->\n<div class=\"wp-block-vk-blocks-faq2 vk_faq  [accordion_trigger_switch] is-style-vk_faq-normal vk_block-margin-sm--margin-bottom\"><div class=\"vk_faq-header\"></div><dl class=\"vk_faq-body\"><!-- wp:vk-blocks/faq2-q -->\n<dt class=\"wp-block-vk-blocks-faq2-q vk_faq_title\" aria-label=\"質問\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}},\"color\":{\"text\":\"#373737\"}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#373737\"><span style=\"color: #373737;\" class=\"stk-highlight\">店舗が広告主として利用する場合、費用はかかりますか？</span></p>\n<!-- /wp:paragraph --></dt>\n<!-- /wp:vk-blocks/faq2-q -->\n\n<!-- wp:vk-blocks/faq2-a -->\n<dd class=\"wp-block-vk-blocks-faq2-a vk_faq_content\" aria-label=\"回答\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}},\"color\":{\"text\":\"#373737\"}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#373737\"><span style=\"color: #373737;\" class=\"stk-highlight\"><strong>掲載自体は無料で、成果が発生した場合のみ広告費が発生します。<br></strong>無駄な広告費をかけずに、成果報酬型で集客が可能です。</span></p>\n<!-- /wp:paragraph --></dd>\n<!-- /wp:vk-blocks/faq2-a --></dl><div class=\"vk_faq-footer\"></div></div>\n<!-- /wp:vk-blocks/faq2 --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"vk-has-white-color is-style-default\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0px\",\"left\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|30\"}},\"border\":{\"radius\":{\"topLeft\":\"20px\",\"topRight\":\"20px\",\"bottomLeft\":\"20px\",\"bottomRight\":\"20px\"}},\"shadow\":\"var:preset|shadow|natural\"},\"backgroundColor\":\"white\",\"layout\":{\"type\":\"constrained\"},\"color\":\"#ffffff\"} -->\n<div class=\"wp-block-group vk-has-white-color is-style-default has-white-background-color has-background\" style=\"border-top-left-radius:20px;border-top-right-radius:20px;border-bottom-left-radius:20px;border-bottom-right-radius:20px;padding-top:0;padding-right:var(--wp--preset--spacing--30);padding-bottom:0px;padding-left:var(--wp--preset--spacing--30);box-shadow:var(--wp--preset--shadow--natural)\"><!-- wp:vk-blocks/faq2 {\"className\":\"is-style-vk_faq-normal vk_block-margin-sm\\u002d\\u002dmargin-bottom\"} -->\n<div class=\"wp-block-vk-blocks-faq2 vk_faq  [accordion_trigger_switch] is-style-vk_faq-normal vk_block-margin-sm--margin-bottom\"><div class=\"vk_faq-header\"></div><dl class=\"vk_faq-body\"><!-- wp:vk-blocks/faq2-q -->\n<dt class=\"wp-block-vk-blocks-faq2-q vk_faq_title\" aria-label=\"質問\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}},\"color\":{\"text\":\"#373737\"}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#373737\"><span style=\"color: #373737;\" class=\"stk-highlight\">Webや広告に詳しくなくても利用できますか？</span></p>\n<!-- /wp:paragraph --></dt>\n<!-- /wp:vk-blocks/faq2-q -->\n\n<!-- wp:vk-blocks/faq2-a -->\n<dd class=\"wp-block-vk-blocks-faq2-a vk_faq_content\" aria-label=\"回答\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#373737\"}}},\"color\":{\"text\":\"#373737\"}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#373737\"><span style=\"color: #373737;\" class=\"stk-highlight\"><strong>はい。Web知識がなくても問題ありません。<br></strong>REHAP導入店舗様には、Webマーケティングに関する無料相談もご用意しています。</span></p>\n<!-- /wp:paragraph --></dd>\n<!-- /wp:vk-blocks/faq2-a --></dl><div class=\"vk_faq-footer\"></div></div>\n<!-- /wp:vk-blocks/faq2 --></div>\n<!-- /wp:group -->\n\n<!-- wp:vk-blocks/spacer {\"spaceType\":\"height\",\"pc\":120,\"tablet\":50,\"mobile\":40,\"spaceSize\":\"custom\"} -->\n<div class=\"wp-block-vk-blocks-spacer vk_spacer\"><div class=\"vk_spacer-display-pc\" style=\"height:120px\"></div><div class=\"vk_spacer-display-tablet\" style=\"height:50px\"></div><div class=\"vk_spacer-display-mobile\" style=\"height:40px\"></div></div>\n<!-- /wp:vk-blocks/spacer --></div>\n<!-- /wp:group -->\n\n<!-- wp:vk-blocks/spacer {\"spaceType\":\"height\",\"pc\":120,\"tablet\":50,\"mobile\":40,\"spaceSize\":\"custom\"} -->\n<div class=\"wp-block-vk-blocks-spacer vk_spacer\"><div class=\"vk_spacer-display-pc\" style=\"height:120px\"></div><div class=\"vk_spacer-display-tablet\" style=\"height:50px\"></div><div class=\"vk_spacer-display-mobile\" style=\"height:40px\"></div></div>\n<!-- /wp:vk-blocks/spacer -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"vk_block-margin-0\\u002d\\u002dmargin-bottom\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vk-color-primary\"}}}},\"textColor\":\"vk-color-primary\",\"fontSize\":\"huge\"} -->\n<p class=\"has-text-align-center vk_block-margin-0--margin-bottom has-vk-color-primary-color has-text-color has-link-color has-huge-font-size\"><strong>お問合せフォーム</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"vk_block-margin-lg\\u002d\\u002dmargin-bottom\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|vk-color-primary\"}}}},\"textColor\":\"vk-color-primary\"} -->\n<p class=\"has-text-align-center vk_block-margin-lg--margin-bottom has-vk-color-primary-color has-text-color has-link-color\"><strong>CONTACT</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:wpforms/form-selector {\"clientId\":\"bc3d0a65-9188-47d7-9f6b-65187034cebd\",\"formId\":\"170\",\"theme\":\"default-copy-1\",\"themeName\":\"Default (コピー)\",\"copyPasteJsonValue\":\"{\\u0022displayTitle\\u0022:false,\\u0022displayDesc\\u0022:false,\\u0022theme\\u0022:\\u0022default-copy-1\\u0022,\\u0022themeName\\u0022:\\u0022Default (コピー)\\u0022,\\u0022fieldSize\\u0022:\\u0022medium\\u0022,\\u0022backgroundImage\\u0022:\\u0022none\\u0022,\\u0022backgroundPosition\\u0022:\\u0022center center\\u0022,\\u0022backgroundRepeat\\u0022:\\u0022no-repeat\\u0022,\\u0022backgroundSizeMode\\u0022:\\u0022cover\\u0022,\\u0022backgroundSize\\u0022:\\u0022cover\\u0022,\\u0022backgroundWidth\\u0022:\\u0022100px\\u0022,\\u0022backgroundHeight\\u0022:\\u0022100px\\u0022,\\u0022backgroundUrl\\u0022:\\u0022url()\\u0022,\\u0022backgroundColor\\u0022:\\u0022rgba( 0, 0, 0, 0 )\\u0022,\\u0022fieldBorderRadius\\u0022:\\u00223px\\u0022,\\u0022fieldBorderStyle\\u0022:\\u0022solid\\u0022,\\u0022fieldBorderSize\\u0022:\\u00221px\\u0022,\\u0022fieldBackgroundColor\\u0022:\\u0022#ffffff\\u0022,\\u0022fieldBorderColor\\u0022:\\u0022rgba( 0, 0, 0, 0.25 )\\u0022,\\u0022fieldTextColor\\u0022:\\u0022rgba( 0, 0, 0, 0.7 )\\u0022,\\u0022fieldMenuColor\\u0022:\\u0022#ffffff\\u0022,\\u0022labelSize\\u0022:\\u0022medium\\u0022,\\u0022labelColor\\u0022:\\u0022rgba( 0, 0, 0, 0.85 )\\u0022,\\u0022labelSublabelColor\\u0022:\\u0022rgba( 0, 0, 0, 0.55 )\\u0