(437, 2, '2026-03-03 05:14:21', '2026-03-02 20:14:21', '{\n    \"custom_css[lightning-child-sample]\": {\n        \"value\": \".is-layout-constrained > :where(:not(.alignleft):not(.alignright):not(.alignfull)) {\\n    max-width: 85%;\\n}\\n.wp-block-columns.is-layout-flex.wp-container-core-columns-is-layout-e0e4babd.wp-block-columns-is-layout-flex {\\n    width: 50%;\\n}\\n\\n.rehap_shikumi{\\n  width: 55%;\\n  margin: 0 auto;\\n}\\n\\nfooter.site-footer{\\n  background: #942b2b !important;\\n  color: #fff !important;\\n}\\n\\n/* \\u9ad8\\u3055\\u3092\\u300c\\u898b\\u305f\\u76ee\\u3068\\u3057\\u3066\\u300d300px\\u306b\\u3059\\u308b\\uff08padding\\u3067\\u78ba\\u5b9f\\u306b\\u4f38\\u3070\\u3059\\uff09 */\\nfooter.site-footer {\\n  min-height: 200px !important;\\n  display: flex !important;\\n  align-items: center;      /* \\u7e26\\u4e2d\\u592e\\u306b\\u3057\\u305f\\u3044\\u5834\\u5408 */\\n}\\n\\n\\n/* 2\\u884c\\u76ee\\uff08Powered by WordPress\\u301c\\uff09\\u3092\\u975e\\u8868\\u793a */\\n.site-footer .site-footer-copyright p:nth-child(2){\\n  display:none;\\n}\\n\\n@media screen and (max-width: 768px) {\\n  .is-layout-constrained > :where(:not(.alignleft):not(.alignright):not(.alignfull)) {\\n      max-width: 100%;\\n  }\\n\\t\\n\\t.wp-block-columns.is-layout-flex.wp-container-core-columns-is-layout-e0e4babd.wp-block-columns-is-layout-flex {\\n    width: 100%;\\n}\\n\\t\\n\\t :root :where(.is-layout-flex) {\\n    gap: 0px;\\n  }\\n\\t\\n.model_rehap img {\\n  max-width: 80%;\\n  width: 80%;\\n  margin: 30px auto 0;\\n  display: block;\\n}\\n\\t\\n\\t.rehap_shikumi{\\n  width: 90%;\\n  margin: 0 auto;\\n\\tpadding:10px 5px;\\n}\\n\\t.merit {\\n    gap: 30px;\\n}\\n\\t.tenpo_illust {\\n\\t\\tmargin:0 auto;\\n\\t\\tpadding-bottom:0px;\\n\\t\\tpadding-left:0px;\\n\\t\\tpadding-right:0px;\\n\\t\\tgap:5px;\\n\\t}\\n\\t\\n\\t.wp-block-columns.tenpo_illust{\\n  padding: 0 0 20px 0 !important;\\n}\\n\\n.contact_botton {\\n  width: 100vw !important;\\n  max-width: 90vw !important;\\n  margin-left: calc(50% - 50vw);\\n}\\n\\t\\n}\\n\\n\",\n        \"type\": \"custom_css\",\n        \"user_id\": 2,\n        \"date_modified_gmt\": \"2026-03-02 20:14:21\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', 'd31aa0cf-e941-4899-b765-7aa66758edd0', '', '', '2026-03-03 05:14:21', '2026-03-02 20:14:21', '', 0, 'https://relybit.co.jp/rehap/lp/d31aa0cf-e941-4899-b765-7aa66758edd0/', 0, 'customize_changeset', '', 0),
